// Clocked-torque G-SLIP pronk controller.
//
// Runs the SLIP-RF running template of Lu & Lin 2024 on the Corgi, with all
// four legs in phase so they reduce to a single virtual leg.
//
// The template itself is generated by the LegWheel package
// (examples/gslip/export_pronk_csv.py) and loaded here as a reference table,
// which keeps the model in one place rather than duplicating the fixed-point
// solve in C++. Each row is one 1 ms control tick and carries the reference
// pose plus a stance flag.
//
// Two impedance regimes, switched by that flag:
//   STANCE  leg-frame stiffness -- a stiff radial spring along the leg (the
//           virtual k_t the rigid linkage cannot provide) and a soft
//           tangential term, so the leg is compliant along its axis while
//           still tracking the swing.
//   FLIGHT  body-frame position tracking; the leg is unloaded and only has to
//           be repositioned for the next touchdown.
//
// The clocked torque is not optional here. A fine sweep of the model
// (LegWheel examples/gslip/corgi_stability_sweep.py) found no self-stable
// running gait for this geometry at any landing angle, stiffness or speed:
// |dP/dalpha| bottoms out around 1.15. The instability is mild -- an error
// grows ~15% per stride, doubling in about 5 strides -- so this loop has
// ample authority, but without it the gait does not persist.

#include <algorithm>
#include <array>
#include <chrono>
#include <cmath>
#include <cstdlib>
#include <fstream>
#include <memory>
#include <sstream>
#include <string>
#include <thread>
#include <vector>

#include <Eigen/Dense>

#include "ament_index_cpp/get_package_share_directory.hpp"
#include <sched.h>
#include <cerrno>
#include <cstring>
#include <cstdlib>
#include "rclcpp/rclcpp.hpp"
#include "corgi_msgs/msg/impedance_cmd_stamped.hpp"
#include "corgi_msgs/msg/motor_state_stamped.hpp"
#include "corgi_msgs/msg/trigger_stamped.hpp"
#include "corgi_msgs/msg/sim_leg_contact_stamped.hpp"
#include "corgi_msgs/msg/imu_stamped.hpp"
#include "nav_msgs/msg/odometry.hpp"
#include "rcl_interfaces/msg/set_parameters_result.hpp"

struct TemplateRow {
    double t;
    double theta;
    double beta;
    double gamma;
    bool in_stance;
};

class GslipPronkNode : public rclcpp::Node {
public:
    GslipPronkNode();
    void run();

private:
    void trigger_cb(const corgi_msgs::msg::TriggerStamped::SharedPtr msg);
    void motor_state_cb(const corgi_msgs::msg::MotorStateStamped::SharedPtr msg);
    void imu_cb(const corgi_msgs::msg::ImuStamped::SharedPtr msg);
    void contact_cb(const corgi_msgs::msg::SimLegContactStamped::SharedPtr msg);

    // Which gain regime leg i should be in for this row. With contact gating
    // off this is just row.in_stance, i.e. the historical behaviour.
    bool leg_in_stance(int leg, const TemplateRow& row) const;

    bool load_template(const std::string& path);
    void apply_row(const TemplateRow& row);
    void execute_standup_phase();
    void execute_running_phase();

    rclcpp::Publisher<corgi_msgs::msg::ImpedanceCmdStamped>::SharedPtr imp_cmd_pub_;
    rclcpp::Subscription<corgi_msgs::msg::TriggerStamped>::SharedPtr trigger_sub_;
    rclcpp::Subscription<corgi_msgs::msg::MotorStateStamped>::SharedPtr motor_state_sub_;
    rclcpp::Subscription<corgi_msgs::msg::ImuStamped>::SharedPtr imu_sub_;
    rclcpp::Subscription<corgi_msgs::msg::SimLegContactStamped>::SharedPtr contact_sub_;

    corgi_msgs::msg::ImpedanceCmdStamped imp_cmd_;
    corgi_msgs::msg::MotorStateStamped motor_state_;
    corgi_msgs::msg::ImuStamped imu_;

    // --- per-leg contact gating -------------------------------------------
    //
    // WHY. apply_row historically applied ONE row.in_stance to all four legs,
    // because the pronk reduction assumes four legs in phase collapsing to a
    // single virtual leg. Measured, they are 32-45% desynchronised, so a shared
    // schedule cannot match all four: a capture found the controller running
    // FLIGHT gains for ~71% of the time a foot was actually on the ground --
    // holding a loaded leg at ~289 N.m/rad instead of the ~36 N.m/rad virtual
    // spring the template exists to present.
    //
    // Gating the GAIN REGIME (and only that) on measured per-leg contact makes
    // the spring exist whenever the leg is really loaded. The commanded
    // trajectory stays global: theta/beta still come from the template, because
    // that is the gait. Only which stiffness matrix is applied becomes per-leg.
    //
    // !!! TRIED 2026-08-17 AND IT WRECKS THE ROBOT. DO NOT ENABLE. !!!
    //
    // The gate engaged correctly (the startup WARN fired) and the run had to be
    // aborted: legs hopping at visibly different times, then the five-bar
    // geometry inverting on several of them.
    //
    // WHY, and it is a design error not a tuning one. Gains and the reference
    // trajectory are two halves of ONE phase description, and this gates only
    // half of it:
    //
    //   leg still loaded, template in flight  -> STANCE gains (k_tangential
    //       600-900) commanded to track a fast flight swing-back. It cannot,
    //       so the error grows without bound.
    //   leg airborne, template in stance      -> stiff 12000 isotropic against
    //       a slow compression reference, snapping the leg toward a pose it
    //       should not hold.
    //
    // Before the change the command was at least SELF-consistent -- gains and
    // reference both came from row.in_stance -- and merely disagreed with
    // reality. This replaced that with a command that disagrees with ITSELF,
    // which is strictly worse. Nothing catches the result, because theta's
    // 17-160 deg range is a LINKAGE constraint that cannot be a per-joint stop
    // and so is unmodelled (see the joint-limits work).
    //
    // There is also positive feedback: each leg's stiffness follows its own
    // contact, so a leg that lands early gets soft gains early, diverges
    // further, and the legs desynchronise progressively.
    //
    // The principled version is PER-LEG PHASE, not per-leg gains: each leg runs
    // the template with its own clock, advanced by its own touchdown, so gains
    // and reference stay consistent within a leg. That is a real gait
    // scheduler, not a flag. Kept here, off by default, as the record of what
    // was tried and why it failed.
    //
    // 2026-08-20: that scheduler now EXISTS -- event_sched + slave_stance +
    // couple_gain below (log S91-S98, event-scheduler thread). Its own
    // journey recorded three MORE ways to break a loaded leg (backward
    // clock freezes feed the stride period; forward advances command the
    // backswing under load; so does exiting to flight rows before real
    // liftoff), which is why the shipped design never phase-corrects a
    // loaded foot at all: stance is entered on the touchdown event,
    // integrated as rolling (beta-dot = v/L), HELD at beta_LO until
    // measured liftoff, and only flight is clocked. It holds gain honesty
    // at ~0.55-0.6 where every global-clock config decays to ~0.2-0.4.
    bool contact_gated_gains_;          // off by default -- opt in
    int contact_debounce_;              // consecutive samples before switching
    double contact_timeout_s_;          // stale topic -> fall back to template
    std::array<bool, 4> leg_contact_{{false, false, false, false}};
    std::array<bool, 4> leg_contact_stable_{{false, false, false, false}};
    std::array<int, 4> leg_contact_count_{{0, 0, 0, 0}};
    double last_contact_stamp_;
    // mutable so the one-shot staleness warning can fire from the const
    // leg_in_stance(). A gate falling back silently is exactly the class of
    // fault this session kept finding.
    mutable bool contact_stale_warned_;

    // --- Event-driven per-leg gait scheduler (fix-order step 4, Tier 1) ----
    //
    // The principled successor to contact_gated_gains_ (see the post-mortem
    // above): each leg runs the SAME template on ITS OWN clock, advanced by
    // its own debounced touchdown, so gains and reference stay consistent
    // within a leg by construction. Tier 0 (log S92, event-scheduler thread)
    // measured why this is the right shape: the legs are locally coherent
    // (5-stride-window touchdown spread 0.16-0.33) but the shared clock
    // walks away from the feet at ~5-15 ms per stride, so gain honesty
    // decays from ~0.7 toward ~0.3 as the error accumulates. A touchdown
    // snap re-zeros that error once per stride.
    //
    // Snap mechanics: on a debounced rising edge of leg_contact_stable_,
    // the leg clock's error to the stance-onset row is computed, clamped to
    // +-event_snap_limit_s, and consumed by MODULATING THE CLOCK RATE over
    // event_blend_ticks -- never an index jump (a hard snap steps beta_ref
    // by up to snap x max template beta-dot; that bound is computed and
    // logged at load). The per-tick rate is clamped to [0, 2.5] rows/tick:
    // a backward correction FREEZES the clock rather than reversing it,
    // because beta_ref running backwards mid-stance is a torque transient
    // with no upside; a -30-row correction therefore takes ~30 ticks. At
    // most event_snap_per_stride snaps per leg per stride -- the
    // scrape-contact defence (linkage scrapes count as contact in the sim's
    // geometric detector). LIFTOFF IS FREE-RUNNING, deliberately: liftoff
    // is an outcome of stance energetics, falling edges are the
    // scrape-noisier direction, and a late switch to soft flight gains is
    // benign while a late switch to stance gains is the 71% mismatch being
    // fixed. Overrun (row in stance far past template stance duration with
    // no contact) is a diagnostic WARN only.
    //
    // NOT the config of record -- it is OFF, and must stay off. S117:
    // spring_rest_reference STOPS THE HOP DEAD (air 0.0%) at k7150, tested
    // as S114 Cell B. Launch default is false and the banner reads "Radial
    // reference: template trajectory" when it is right.
    //
    // (With it ON, theta_ref would be CONSTANT, so per-leg theta divergence
    // would only appear via flight rows. That is the geometry of a
    // configuration nobody should be running.)
    //
    // event_sched=false is EXACTLY off: the stride loop calls the same
    // apply_row(template_[index]) as before this existed (the gamma_openloop
    // dir==0 pattern). Engagement needs ~1 kHz contact
    // (CORGI_CONTACT_INTERVAL=1): the message rate is measured over the
    // settle window and engagement is REFUSED below ~500 Hz, falling back
    // to the global clock. Contact staleness (contact_timeout_s_ machinery)
    // stops snapping and SLEWS each leg clock back to the master through
    // the same rate-modulation path -- a dead sensor degrades to the old
    // controller, never a frozen per-leg state.
    bool event_sched_;
    double event_snap_limit_s_;
    int event_blend_ticks_;
    int event_snap_per_stride_;
    int event_arm_strides_;
    double stance_max_overrun_ratio_;
    // Advance-only snapping (log S95). A backward correction is executed
    // as a clock FREEZE, and on a clocked-trajectory plant the freeze
    // lengthens the physical stride 1:1 (held beta_ref prolongs stance),
    // so the phase error regenerates every stride -- both the 30 ms and
    // 120 ms budgets parked in the same e ~ +100-row attractor (S94/S95
    // traces). Advancing instead shortens the commanded cycle: negative
    // feedback. With this on, a correction more backward than
    // EVENT_BACKWARD_TOL_ROWS is replaced by the complementary FORWARD
    // correction to the next onset (corr += n_rows). false = S94
    // behaviour, bit-identical.
    bool event_forward_only_;
    bool event_engaged_{false};       // rate check + label check passed
    bool sched_labels_ok_{false};     // one contiguous circular stance segment
    size_t stance_onset_row_{0};
    size_t stance_rows_{0};
    double template_dt_{0.001};       // row duration, s
    double sched_hard_snap_beta_deg_{0.0};  // logged bound, computed at load
    std::array<size_t, 4> leg_index_{{0, 0, 0, 0}};
    std::array<double, 4> leg_frac_{{0.0, 0.0, 0.0, 0.0}};
    std::array<double, 4> snap_rows_pending_{{0.0, 0.0, 0.0, 0.0}};
    std::array<int, 4> blend_ticks_left_{{0, 0, 0, 0}};
    std::array<int, 4> snaps_this_stride_{{0, 0, 0, 0}};
    std::array<bool, 4> leg_prev_contact_{{false, false, false, false}};
    std::array<bool, 4> leg_armed_{{false, false, false, false}};
    std::array<long, 4> arm_at_stride_{{-1, -1, -1, -1}};
    std::array<int, 4> stance_run_ticks_{{0, 0, 0, 0}};
    std::array<bool, 4> overrun_flagged_{{false, false, false, false}};
    long contact_msg_count_{0};
    bool sched_stale_active_{false};
    std::ofstream sched_csv_;
    long sched_tick_count_{0};
    void sched_reset(size_t master);
    void sched_tick(size_t master, size_t master_stride, double t_now);
    void sched_advance();

    // --- Tier 3: velocity-slaved stance sweep (log S96) --------------------
    //
    // The no-jump-by-construction successor to touchdown snapping. Three
    // ways of correcting phase on a loaded foot all failed mechanically
    // (S94/S95: backward blend = period-feeding freeze; hard snap = a
    // ~30 deg reference kick; forward advance = a commanded backswing
    // that walks the robot BACKWARDS -- caught on the render). So during
    // stance the absolute clocked beta(t) is abandoned entirely: on a
    // debounced touchdown the leg enters SLAVED STANCE -- beta_ref
    // integrates beta_dot = v / L(theta_measured) from the beta the leg
    // was commanded that very tick (state-continuous), gains take the
    // stance regime, the row pins at the stance onset (labels/gamma).
    // Exit on the FIRST of: relative sweep complete (the template's
    // stance sweep length), measured liftoff, or timeout
    // (stance_max_overrun_ratio x template stance rows). At exit the
    // clock jumps to the liftoff row and the residual beta offset blends
    // to zero across the flight rows (the stance_sweep_scale precedent),
    // so the next touchdown meets the template's beta again. Flight
    // stays clocked; stance duration adapts to the actual speed, which
    // is the period-mismatch fix the snap could never be.
    //
    // L(theta) comes from config/gslip_ltheta_lut.csv, generated from
    // LegWheel's own LegLengthMap (export_ltheta_lut.py) so the length
    // convention matches the template generator BY CONSTRUCTION
    // (L(100 deg) = 0.2931 m = the template l0). v comes staged:
    // slave_v_source=fixed first (mechanism validation, no estimator in
    // the loop), then =ekf (/ekf body twist). ekf staleness > timeout ->
    // 0.1 s hold -> fall back to plain clocked replay (no snapping) with
    // a one-shot WARN; absent at start -> refuse engagement.
    bool slave_stance_;
    std::string slave_v_source_;
    double slave_v_fixed_;
    double ekf_timeout_s_;
    bool slave_engaged_{false};     // param on + LUT ok + source ok
    bool slave_active_{false};      // false while ekf-stale fallback holds
    bool lut_ok_{false};
    std::vector<double> lut_theta_, lut_L_;
    size_t liftoff_row_{0};
    double stance_sweep_rad_{0.0};  // signed, template beta_LO - beta_onset
    double beta_lo_abs_{0.0};       // template's absolute liftoff beta
    std::array<bool, 4> leg_slaved_{{false, false, false, false}};
    // Sweep-complete-but-foot-still-loaded: HOLD beta_LO with stance
    // gains until the measured falling edge (or the timeout). The
    // handover guarded liftoff-before-sweep; the fixed-v probe exposed
    // the mirror case -- exiting to flight rows under load plays the
    // swing-back against the ground and drives the robot BACKWARDS
    // (render, 2026-08-20, third backward signature). The stance
    // reference must never command the backswing while loaded.
    std::array<bool, 4> slave_hold_{{false, false, false, false}};
    // --- Push-timing pair synchronisation (log S100) -----------------------
    //
    // Slaved stance fixed WITHIN-leg consistency; coupling could not fix
    // BETWEEN-leg phase, because the S17 pitch seesaw regenerates the
    // front/rear split during stance and flight-row nudging cannot outrun
    // it (S99: coupling saturates at ~50 rows, flight ceilings ~0.15).
    // So synchronise the PUSH instead of the clock: a leg entering stance
    // waits (beta_ref pinned at entry beta, stance gains, no integration)
    // until `push_sync_quorum` legs are simultaneously slaved AND in
    // contact; all waiting legs then release on the same tick.
    //
    // This delays a leg, which S94's freeze also did -- but there the
    // delay corrected phase BACKWARDS and lengthened the stride, so the
    // error regenerated (positive feedback). Here the early leg waits for
    // the LATE leg's touchdown, so its period stretches toward the late
    // leg's arrival and they land together next stride: the delay is the
    // entrainment. And it honours the S1 invariant -- beta_ref never
    // moves on a loaded foot while waiting.
    //
    // Escapes: per-leg timeout (release alone), own falling edge (normal
    // exit), staleness fallback. push_sync=false is bit-identical off.
    // SOLE-SUPPORT GUARD (added after the first probe run, log S100): a
    // held foot does not roll, so a leg holding while it is the ONLY foot
    // down is a PIVOT under a descending body -- the first probe run
    // nose-dived onto the front-right foot on hop 1 and never recovered
    // its symmetry. A leg that is sole support therefore always releases
    // immediately and sweeps. Fourth entry in the loaded-foot catalogue:
    // you may not freeze a lone stance leg's roll either.
    //
    // ARM DELAY: the settle leaves all four feet down, so no rising edge
    // exists until after hop 1 -- exactly the worst moment to start
    // holding legs. push_sync_arm_strides master strides must pass before
    // any leg waits, so sync engages on a cycling gait, not on entry.
    bool push_sync_;
    int push_sync_quorum_;
    double push_sync_max_hold_s_;
    int push_sync_arm_strides_;
    std::array<bool, 4> slave_wait_{{false, false, false, false}};
    std::array<int, 4> wait_ticks_{{0, 0, 0, 0}};
    long push_rel_quorum_{0}, push_rel_timeout_{0}, push_rel_sole_{0};
    std::array<double, 4> slave_beta_{{0.0, 0.0, 0.0, 0.0}};
    std::array<double, 4> slave_entry_beta_{{0.0, 0.0, 0.0, 0.0}};
    std::array<int, 4> slave_ticks_{{0, 0, 0, 0}};
    std::array<double, 4> flight_off_{{0.0, 0.0, 0.0, 0.0}};
    std::array<double, 4> last_beta_base_{{0.0, 0.0, 0.0, 0.0}};
    // Scrape/bounce defence for slave entries -- the analogue of the snap
    // path's 1-per-stride latch, which the first Tier 3 probe was missing:
    // a contact bounce right after a sweep completed re-entered stance and
    // re-swept from the current beta, ratcheting the reference forward
    // past vertical (backwards walking, caught on the render 2026-08-20).
    // A leg may re-enter slaved stance only after its clock has replayed
    // at least half the flight rows since the last exit (first entry after
    // arming is exempt -- the clock position is inherited from the master
    // and means nothing yet).
    std::array<bool, 4> slave_ever_{{false, false, false, false}};
    // Defensive depth: the integrated beta may never leave the template's
    // own beta range by more than this margin; hitting the clamp forces an
    // exit and WARNs (a runaway reference must not be able to exist).
    double tpl_beta_min_{0.0}, tpl_beta_max_{0.0};
    // --- Tier 2: gentle cross-leg phase coupling (log S97) -----------------
    //
    // With stance slaved to each leg's own touchdown, nothing couples the
    // four clocks: each leg runs a private hop cycle, touchdowns never
    // cluster, and the pronk degenerates to uncoordinated bouncing in
    // place (render, 2026-08-20). Each tick, every armed FREE-RUNNING leg
    // in its FLIGHT rows is nudged toward the four-leg mean phase by
    // clamp(couple_gain * circ_err_rows, +-couple_clamp) rows/tick -- the
    // S89 gentle-hold pattern: small gain, hard clamp, cannot saturate,
    // and it never fights the ground (stance legs are never nudged; a
    // slaved leg contributes its phase but is not nudged). couple_gain
    // 0.0 = off, bit-identical.
    double couple_gain_;
    double couple_clamp_;
    double leg_phase_rows(int i) const;  // clock position incl. slave progress
    double ekf_v_{0.0};
    double ekf_stamp_{-1.0};
    bool ekf_fallback_warned_{false};
    rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr ekf_sub_;
    void ekf_cb(const nav_msgs::msg::Odometry::SharedPtr msg);
    bool load_ltheta_lut(const std::string& path);
    double lut_L(double theta) const;
    double meas_theta(int leg) const;
    void slave_exit(int leg, size_t master, double t_now, const char* why);
    void sched_event(double t, int leg, size_t master, const char* ev);
    double circ_rows(double a, double b) const;  // signed shortest a-b, rows
    void apply_rows(const std::array<const TemplateRow*, 4>& rows);

    // Constant rotation of the template's in_stance labels, seconds; positive
    // delays the gain switch. See load_template for the measurement and the
    // reasoning. 0.0 = shipped behaviour, bit-identical.
    double stance_label_shift_s_;

    // Fraction of the cycle the in_stance labels should span; the window is
    // resized by moving the LIFTOFF edge only, onset untouched, so it composes
    // with the shift (shift places the onset, duty sets the length). See
    // load_template. 0.0 = off, template's own labels, bit-identical.
    double stance_label_duty_;

    // beta-dot slaving (S29): scale the stance beta sweep about touchdown by
    // f = v_slave / v_design, so rolling holds at f times the template's
    // design speed. See load_template. 1.0 = off, bit-identical.
    double stance_sweep_scale_;

    // contact_align (S309, Open Issue #20): load-time COMMON-MODE rewrite
    // of the beta column into DWELL (D rows at the touchdown beta) ->
    // ROLL-MATCHED SWEEP (the template's own normalised sweep shape
    // resampled onto S rows at amplitude f*A) -> linear RETURN, so the
    // commanded sweep occupies where feet are MEASURED to be down
    // (per-leg phi_TD table: TD ~row 72-75 of the 0-107 label stance,
    // common-mode within 3 rows). Touchdown-row beta is PINNED -- the
    // S112/S113 rotation class moved it and was falsified; this changes
    // only the reference's velocity profile. theta/gamma/labels/row 0
    // untouched; no runtime state, no trigger -- desync is inexpressible
    // (S101) and the loaded-foot invariant is vacuous. rows=0 = off,
    // bit-identical (early return before any table write).
    int contact_align_rows_;      // D; 0 = off
    int contact_sweep_rows_;      // S; 0 -> label stance length m
    double contact_sweep_scale_;  // f in (0,1]
    int contact_ramp_rows_;       // R pre-sweep retraction ramp; 0 = none

    std::vector<corgi_msgs::msg::ImpedanceCmd*> imp_cmd_modules_;
    std::vector<TemplateRow> template_;

    bool trigger_;
    bool sim_;

    // Stance: the virtual leg spring, split across four legs in a pronk.
    // k_radial = k_rel * m * g / l0 / 4 with k_rel = 18, at the nominal stance
    // theta = 100 deg (l0 = 0.1481 m, hip 0.2931 m) -> 8941 N/m per leg.
    //
    //   m = 30.00 kg  measured on scales
    //   m = 30.84 kg  summed from CorgiRobotABAD.proto -- agrees to 2.8%
    //
    // so one value covers both. Peak motor torque ~14 N.m, 41% of the limit.
    //
    // The nominal stance is deliberately NOT the paper's r~ = 0.6303 optimum,
    // which for this robot is a 0.230 m crouch. Standing at 0.293 m instead
    // costs only a slope penalty (1.154 -> 1.232) and buys a 26% lower peak
    // ground reaction, 41% rather than 53% torque, and a 43% softer spring --
    // the last mattering most, since a softer virtual spring is much less
    // corrupted by the 0.36-0.68 N.m joint friction. See LegWheel
    // examples/gslip/stance_height_tradeoff.py.
    //
    // Only the stiffness would change with mass anyway: since
    // k = k_rel*m*g/l0, the ratio k/m is mass-independent and the stance EOM
    // divides through by m, so the template, the fixed point (beta 74.75 deg,
    // alpha 23.75 deg) and the GRF in body weights are all identical.
    //
    // k_lateral holds the ABAD axis. It must NOT be zero: with leg_frame the
    // lateral axis is the ABAD direction, so K_joint = J^T K J would give a
    // near-zero kp_h and the hip roll would go floppy.
    //
    // Sizing it from the 0.0917 m ABAD-to-wheel-plane offset was wrong. At
    // k_lateral = 30000 the measured kp_h was 972 N.m/rad, not the ~250
    // intended, so the effective moment arm in the Jacobian is nearer 0.18 m.
    // That over-stiff ABAD fed large off-diagonal coupling torques into the
    // leg motors: applied torque peaked at 33-35 N.m against the 35 N.m limit
    // while the model predicted 14 N.m, and the leg could not reach its
    // commanded extension because it was torque-limited, not
    // stiffness-limited. 7500 N/m gives roughly the 250 N.m/rad originally
    // wanted, which held gamma to about 1 degree.
    // b_radial defaults to ZERO, and that is deliberate. The G-SLIP model is
    // conservative: the spring returns everything it stores, so any radial
    // damping is a deviation from the model rather than a refinement of it.
    // The original 72 came from a rule of thumb (0.008*k), not the physics.
    //
    // An energy audit over the hop showed why it mattered. At b_radial = 72
    // the motors did 105 W of positive work and took 99.6 W straight back out,
    // netting only 5.5 W: energy was being absorbed during extension as fast
    // as the spring released it, so the body decelerated while still in
    // contact and never lifted off. At b_radial = 0 the braking work fell to
    // 77.6 W, net rose to 27.9 W, peak vertical velocity went 1.109 -> 1.503
    // m/s and the flight phase went 4.0% -> 31.9%.
    double k_radial_;
    double k_tangential_;
    double k_lateral_;
    double b_radial_;
    double b_tangential_;
    double b_lateral_;

    // --- Clocked-torque feedforward: eq 11's D term (log S164) ------------
    //
    // Lu & Lin 2024 eq 11 damps the leg angle to the CLOCK'S rate,
    // k_D*(dtheta_fp - dtheta). This controller damped to zero, i.e. it
    // carried an unintended brake proportional to the commanded sweep rate.
    // clock_ff_scale_ 0.0 reproduces that exactly; 1.0 is the paper's law.
    // clock_ff_phase_ "stance" | "both" -- the paper says BOTH (p5, S2.3),
    // the registered predictions P-N-1..3 are about stance.
    double clock_ff_scale_;
    std::string clock_ff_phase_;
    double clock_rate_stance_{0.0};   // rad/s, derived from the template
    double clock_rate_flight_{0.0};   // rad/s, signed opposite
    // TRUE only inside the stride loop. The clock torque references a clock;
    // during standup, the pre-trigger hold and the settle there is no clock
    // running, the commanded beta is FROZEN, and a constant tangential force
    // against a static pose is just a lean: at equilibrium the lever cancels
    // and the leg sits at (b_tangential/k_tangential)*dbeta_ref = 0.1505 rad
    // = 8.6 deg for the whole 2.5 s settle. That is larger than the +0.1382
    // rad tracking lag the campaign validates against, and it would put the
    // treated arms into the gait from a different initial condition than the
    // off arm -- a confound manufactured by the instrument.
    bool gait_striding_{false};

    // --- Commanded lateral force: steering by FORCE, not by lean ------------
    //
    // ImpedanceCmd carries fx/fy/fz straight into
    //     trq_cmd_base = J^T * force_des        (force_control.cpp:173)
    // and this controller has always sent zeros there. Populating fy is the
    // cheapest available lateral ground reaction: no k_lateral re-tune, no new
    // estimator, and M = 0 so nothing else in that expression wakes up. Note
    // force_control also builds a force_err (line 80) and never uses it, so a
    // non-zero fy does NOT close any force-feedback loop -- which matters,
    // because force_state is not trustworthy in sim.
    //
    // WHY THIS EXISTS. Camber steers by rolling the contact along a curved
    // path, and S33 measured that at 0.02% of its geometric turn. This is the
    // other route to the same turn: a lateral ground reaction and its yaw
    // moment. Same ABAD joint, different physics. S33 could not have seen it --
    // its peak |tau_h| was 3.8-7.0 N.m because the legs ACHIEVED their
    // commanded camber, so the lateral spring sat at rest and produced almost
    // no force. Lateral force needs a demand the foot must resist.
    //
    // FRAME. fy is PER-LEG, not body frame. force_control builds the leg
    // kinematics from ROS gamma (the driver un-mirrors it at
    // corgi_driver.py:514) and ROS gamma > 0 abducts OUTWARD on all four legs,
    // so +fy is outward on all four. Converting a body-frame command therefore
    // needs the left/right selector {+1,-1,-1,+1} -- the same partition as
    // roll_sign and steer_sign, and NOT dir_abad{+1,-1,+1,-1}, which is the
    // mounting mirror the driver already applies on the way out.
    //
    // SIGN. J^T maps the force the FOOT exerts on the GROUND, so pushing the
    // feet toward +y accelerates the body toward -y. f_lateral_ is declared as
    // the force on the BODY (positive = body +y = LEFT) and negated here. If it
    // pushes the wrong way, negate the parameter -- same idiom as the attitude
    // gains, and for the same reason.
    //
    // GATING. Stance only (unloaded feet just get flung), and only once
    // yaw_ref_set_ is true, which is the existing "template is actually
    // running" flag that gamma_correction already uses. Without the second
    // gate the settle phase (in_stance = true, execute_running_phase) would be
    // pushed sideways before the first stride and bias the initial condition.
    //
    // UNITS: newtons per stance leg. Torque is clamped downstream per joint
    // (leg 29.5 / ABAD 44.25), so an over-large demand saturates rather than
    // exploding -- but it will still tip the robot, so ramp it.
    //
    // f_lateral_front_only_ applies it to A,B only. All four is a pure lateral
    // push (crab, no yaw) and isolates "does the channel produce force at all".
    // Front-only adds the yaw moment and is the steering test, and is what the
    // turning-strategies paper does (forelimbs steer, hindlimbs do not).
    double f_lateral_;
    bool f_lateral_front_only_;
    double lateral_force(int leg_index, bool in_stance) const;

    // Flight: body-frame position tracking on an unloaded leg.
    //
    // These have to be STIFF, not gentle. theta = 100 deg is the touchdown
    // pose and is reached at the END of flight, so the leg must retract and
    // re-extend through the full 15.6 deg sweep in the 127 ms flight window.
    // At k_flight = 2000 it managed only 50% of the commanded excursion and
    // touched down 11 deg short, which left the spring far less compression
    // than the template assumes, weakened push-off, and killed the flight
    // phase entirely. The leg is unloaded here, so stiff tracking is cheap.
    double k_flight_;
    double b_flight_;

    int standup_ticks_;

    // --- Body attitude correction through the ABAD joints -------------------
    //
    // The clocked-torque template shapes where the LEGS go; it contains no
    // body-level feedback at all. With |dP/dalpha| ~ 1.23 the gait is
    // unstable, so a symmetric start develops an asymmetry that grows: the
    // measured pronk stayed level in roll and pitch (< 1.5 deg) but yawed
    // 14.8 deg in 10 s, driven by the right legs carrying ~50% more contact
    // time than the left. Nothing in the controller opposed it.
    //
    // The paper's TWIX gets away without this because an alternating tripod
    // is inherently yaw-symmetric. A four-legged pronk is not.
    //
    // gamma tilts the leg laterally, moving the contact point sideways, so
    // differential gamma generates the lateral ground reaction needed for
    // roll and yaw moments:
    //   roll : left legs one way, right legs the other   (A,D vs B,C)
    //   yaw  : front legs one way, rear legs the other   (A,B vs C,D)
    //
    // Gain SIGNS are not obvious from the geometry -- if a correction makes
    // things worse, negate the gain. They are parameters for that reason.
    void update_attitude(double& roll, double& pitch, double& yaw) const;
    double gamma_correction(int leg_index) const;

    // --- Body PITCH through differential leg length (log S115) --------------
    //
    // gamma_correction has a roll channel and a yaw channel and no pitch
    // channel: pitch_ was computed every tick and never read. The reason
    // is in the comment above -- "the measured pronk stayed level in roll
    // and pitch (< 1.5 deg) but yawed 14.8 deg in 10 s" -- so pitch was
    // dropped because it was small.
    //
    // It is no longer small. Measured 2026-08-20 on every flying config:
    // pitch 18-34 deg PEAK-TO-PEAK, RMS 3.5-4.8 deg, while roll stayed
    // under 2 deg exactly as that comment predicted. And landing pitched
    // measurably degrades that stance: rho(|pitch at touchdown|, beta
    // swept) = -0.32/-0.36 on the recommended k7150 config. This is the
    // S17 pitch seesaw seen on the BODY -- the same mode the per-leg
    // scheduler ladder (S91-S102) failed to fix from the leg-timing side,
    // because the legs were never the free variable.
    //
    // gamma cannot make pitch: it tilts legs laterally. Pitch needs
    // fore/aft asymmetry, and the direct actuator is LEG LENGTH -- extend
    // the front pair while retracting the rear and the body pitches nose
    // up. So this adds to theta, with the front/rear partition yaw_sign
    // already uses:
    //
    //     theta_i += pitch_sign[i] * clamp(k_pitch*pitch + d_pitch*wy)
    //     pitch_sign = {+1, +1, -1, -1}   (A,B front;  C,D rear)
    //
    // SIGN is not derivable from the geometry (it depends on which way
    // the linkage opens against the body frame) -- take it from an
    // open-loop pair and negate if the correction makes things worse,
    // the same rule k_roll/k_yaw carry.
    //
    // STANCE-GATED. A leg only pitches the body when it has ground to
    // push against; applying this in flight would just wave the leg and
    // corrupt the touchdown pose, which is the fault this is meant to
    // reduce. Same gate as lateral_force, and gated on yaw_ref_set_ so
    // the settle is untouched.
    //
    // theta is the LINKAGE-CONSTRAINED axis (17-160 deg, a five-bar fold
    // that is not a per-joint stop and so is unmodelled), so the clamp
    // matters more here than it does for gamma. pitch_limit_ defaults to
    // 3 deg, an order of magnitude inside the fold from the ~90-100 deg
    // operating range, and CORGI_THETA_STOP remains the backstop -- but
    // the clamp must not RELY on the stop.
    //
    // k_pitch = 0.0 is EXACTLY off: returns literal 0.0 before touching
    // anything, so every run recorded before this existed is reproducible
    // (the gamma_openloop dir==0 pattern).
    double pitch_correction(int leg_index, bool in_stance) const;

    // --- Open-loop Ackermann camber pair (Stage 3 mechanism demo) -----------
    //
    // A held left/right camber differential: the pair on the turn side leans
    // harder (lam_in), the outer pair follows at the apex-condition angle
    // (lam_out), both toward the turn centre -- the rolling geometry that a
    // pair of cambered wheels needs to share one turn apex. Magnitudes come
    // from ackermann_pair() offline (LegWheel cambered_return_map.py /
    // camber_roll.py --acker); NO geometry lives here.
    //
    // gamma_acker_dir_ = 0 (the default) returns literal 0.0 before touching
    // anything, so every run without the flag is bit-identical to before this
    // existed. Applied additively in apply_row next to gamma_correction, and
    // clamped by its OWN limit -- gamma_limit_ clamps only the feedback term.
    double gamma_openloop(int leg_index) const;

    // --- Steering: differential beta ----------------------------------------
    //
    // gamma above is INERT in yaw. Measured: k_yaw = 0 collapses gamma from
    // +-5 deg pinned to +-0.3 deg and leaves the heading trajectory unchanged,
    // while the correction saturates 67-78% of the time. The robot yaws right
    // at 2.3-3.6 deg/stride whatever the controller does -- and it does it in
    // the in-place hop too, where beta is identically zero, so the yaw is
    // intrinsic to the plant. That is a MISSING ACTUATOR, not a gain to tune;
    // see "The yaw problem, consolidated" in the weekly progress log for the
    // eleven candidate causes already eliminated.
    //
    // The channel added here is differential beta. The foot is a circular arc
    // of radius 0.145 m and stance is ROLLING contact, so sweeping a leg by
    // d_beta while it is down rolls that side forward by ~r*d_beta: during
    // stance the robot is a differential drive. Unequal left/right sweep yaws
    // it,
    //
    //     d_psi ~ r * (sweep_L - sweep_R) / track,    track = 0.24 m
    //
    // which for a 5 deg sweep differential predicts 0.145*0.0873/0.24 = 0.053
    // rad ~ 3.0 deg/stride -- comparable to the parasitic rate, so the channel
    // is plausibly strong enough to cancel it as a disturbance without ever
    // finding its cause.
    //
    // CAVEAT, recorded because it is easy to forget: differential rolling
    // already FAILED as an explanation of the parasitic yaw (per-stride
    // correlation -0.011, n=150). That tested whether INCIDENTAL sweep
    // differences predict the EXISTING yaw. Whether a COMMANDED differential
    // steers is a different claim, and open. The mean rates did agree
    // (predicted 3.4-4.8 vs measured 2.9-3.4 deg/stride), so the magnitude
    // scale is right. Test open-loop first.
    //
    // Two forms, because neither covers both regimes:
    //
    //   steer_offset  a per-side beta offset, applied ONLY while in stance.
    //                 Works everywhere, including the hop. It has to be
    //                 stance-gated to do anything: in the hop row.beta is
    //                 identically 0 for the whole stride, so a CONSTANT offset
    //                 is a static leg angle, not a sweep, and under a rolling
    //                 model it rolls nothing. Gated, the leg is driven to +-s
    //                 during contact and returns in flight, which is a real
    //                 differential roll of ~s per side.
    //
    //   k_steer       per-side amplitude scale, beta * (1 +- k_steer). Only
    //                 does anything where the template already sweeps, i.e.
    //                 the forward rungs. Changes fore-aft impulse as well as
    //                 yaw, so speed moves a little -- that is how a
    //                 differential drive works.
    //
    // Both default to ZERO so this is a no-op until a run asks for steering.
    // The members themselves live below gamma_limit_, so the declaration order
    // matches the constructor's initialiser list (-Wreorder).
    double steer_command() const;

    // --- Commanded turns: a ramping heading reference ------------------------
    //
    // The steering channel above holds a HEADING; turning is the same channel
    // tracking a heading that moves. yaw_ref_ is latched once after the settle
    // and then advanced by turn_rate_ every tick, so steer_command() sees a
    // rotating reference and the control law is untouched. turn_rate_ = 0 leaves
    // the reference latched and reduces this EXACTLY to the heading hold, which
    // is what keeps every result recorded before turns existed reproducible.
    //
    // Radius follows from the speed: R = v / turn_rate. At the measured
    // top-rung 0.787 m/s, R = 2.0 m wants 0.394 rad/s.
    void advance_yaw_ref(double dt);

    // Rest-length leg extension, taken from the template's maximum theta
    // (its touchdown pose, where the spring is uncompressed).
    double theta_rest_{0.0};
    bool spring_rest_reference_;

    double roll_{0.0}, pitch_{0.0}, yaw_{0.0};
    double yaw_ref_{0.0};
    bool yaw_ref_set_{false};

    double k_roll_;
    double d_roll_;
    double k_yaw_;
    double d_yaw_;
    double gamma_limit_;   // rad, clamp on the correction
    // Separate clamp on the YAW part of gamma_correction alone (rad).
    // 0 = off, code path identical to before the parameter existed. The
    // default yaw hold saturates the shared 5 deg gamma_limit_ in every
    // baseline (log s87) and contaminates gamma; a hold clamped to ~1 deg
    // CANNOT saturate into the commanded lean, and the antisymmetric
    // Menger headline cancels what it adds (log s89, C2).
    double gamma_yaw_limit_;

    // Pitch channel; see pitch_correction(). rad and rad/(rad/s).
    double k_pitch_;
    double d_pitch_;
    double pitch_limit_;   // rad, clamp on the theta perturbation

    // --- Apex beta feedback (log S133-S135) --------------------------------
    // ONE row of the Stage 2b return-map deadbeat, re-solved at the PLANT's
    // operating point rather than at v~0.70, and reduced to the only input
    // direction that survives regularisation down here.
    //
    // WHAT THIS IS NOT. It is not the full deadbeat. At the plant's point
    // sigma(beta) = 2.893 against sigma(differential camber) = 0.332, so
    // rcond = 0.2 cuts the camber rows to ~5e-4 and the rho/rho_dot columns to
    // zero. The full gain (rcond 1e-2) has max element 53.5, demands 104 N.m
    // against the ABAD's 44.25 ceiling, clips, and ends up WORSE than passive
    // (mean 1.0 strides vs 3.6). So the camber channel is deliberately absent:
    // it is not usable at this speed, and pretending otherwise costs torque
    // the robot does not have.
    //
    // ^ CORRECTED 2026-08-29: those sigma/torque numbers were the broken
    // crown coefficient talking (R_CORNER 0.015 for the rolling radius
    // 0.14482 -- log S183, LegWheel 18bee69). Post-fix, differential camber
    // is a genuine second actuator (J_u SVs 3.06 / 2.89 at the re-solved
    // plant orbit, S263) and the channel now exists as the apex
    // differential-camber block below -- still default off.
    //
    // What survives is beta responding to forward speed and apex height --
    // foot placement, evaluated once per stride at apex and held:
    //
    //     d_beta = gain * ( k_vx*(vx - vx*) + k_h*(h - h*) )
    //
    // With apex_fb_gain_ = 0.0 (the default) d_beta is identically 0.0 and
    // cmd->beta is bit-identical to every run recorded before this existed.
    double apex_fb_gain_;      // scalar on the whole correction; 0 = off
    double apex_k_vx_;         // K row 0, vx column
    double apex_k_h_;          // K row 0, h column
    double apex_vx_star_;      // m/s, the fixed point this regulates to
    double apex_h_star_;       // m
    double apex_beta_limit_;   // rad, clamp on d_beta
    double apex_beta_offset_{0.0};   // held across the stride
    // Apex detection state: vz crossing + -> - while no leg is down.
    double ekf_vx_{0.0}, ekf_vz_{0.0}, ekf_z_{0.0};
    double ekf_vz_prev_{0.0};
    bool apex_armed_{false};
    long apex_count_{0};
    bool apex_starved_warned_{false};
    std::string apex_odom_topic_;
    // S296 latch-and-defer: ~half of true apexes pass while a foot is
    // still down (rear-pair flights are 60-70 ms and fragmented), and
    // the old single-tick predicate consumed those edges for the whole
    // stride. A grounded crossing now latches here, with the K-row
    // inputs sampled AT the crossing, and applies at the first stable-
    // airborne tick (>= 2 contact samples old). Expires after 0.30 s.
    bool apex_pending_{false};
    double apex_pending_s_{-1.0};
    double apex_pending_vx_{0.0}, apex_pending_z_{0.0};
    double apex_pending_vy_{0.0}, apex_pending_roll_{0.0};
    double apex_pending_wx_{0.0};
    int apex_airborne_ticks_{0};
    void update_apex_feedback();
    void apex_fire(double now_s, double vx, double z, double vy,
                   double roll_v, double wx);
    void apex_vz_prev_guard();

    // --- Apex differential camber: the deadbeat's SECOND input --------------
    //
    // K's lam_l row at the plant orbit of record (S263: "measured" radius
    // law, v_td 0.410, x* = [vx 0.3106, vy 0, h 0.2886, rho 0, drho 0]),
    // extracted 2026-08-29 from cambered_return_map.deadbeat_gain(rcond 1e-2)
    // with the orbit self-checked against S263's printed SVs (3.06, 2.89,
    // 4.3e-6). The lam_r row is the exact mirror at this symmetric orbit,
    // and the vx/h columns (~0.004) are dropped: symmetric camber is the
    // model's null direction (third J_u SV). vy*/rho*/drho* are 0 at this
    // orbit, so no star parameters exist; gains are per-orbit facts (S57) --
    // re-extract before running any other orbit.
    //
    //     d_lam = gain * ( k_vy*vy + k_rho*rho + k_drho*drho )
    //
    // evaluated at the same apex event as the beta row, held across the
    // stride, applied as gamma += lr_sign * d_lam (A,D = +d_lam,
    // B,C = -d_lam). Mapping: model lambda > 0 leans the wheel OUTBOARD for
    // its side and grows the hip->contact offset d_out (side_geometry
    // docstring), which is exactly gamma > 0 = abduct outboard, so gamma is
    // lambda sign-for-sign per side. Sanity: rho > 0 (lean right) moves both
    // contacts rightward -- foot placement under the fall.
    //
    // SIGN CHECK BEFORE ANY SCORING RUN (the S88 lesson): tip the plant and
    // verify the commanded gamma move matches the direction above. vy enters
    // from the same odom topic as the beta row and shares its ground-truth
    // caveat; rho/drho are IMU (roll_ is one tick stale at the apex event,
    // negligible against the clamp).
    //
    // With apex_dc_gain_ = 0.0 (the default) d_lam is identically 0.0 and
    // cmd->gamma is bit-identical to every run recorded before this existed.
    double apex_dc_gain_;      // scalar on the whole correction; 0 = off
    double apex_dc_k_vy_;      // K lam_l row, vy column
    double apex_dc_k_rho_;     // K lam_l row, rho column
    double apex_dc_k_drho_;    // K lam_l row, drho column
    double apex_dc_limit_;     // rad, clamp on d_lam
    double apex_dc_offset_{0.0};   // held lam_l offset; B,C get the mirror
    double ekf_vy_{0.0};
    double apex_diffcamber(int leg_index) const;

    // Hold decay -- the S268 latch-up fix. A correction bad enough to kill
    // flight also kills the apex events that would replace it, so a held
    // offset can freeze at full scale with no path back: watched happening
    // in the S268 sign check (clamp pegged at apex #1, ~18 s latched, gait
    // dead). If no apex has fired for apex_hold_grace_s, BOTH held offsets
    // bleed linearly to zero over apex_hold_decay_s (per-row rate = that
    // row's clamp / decay_s, so a full-scale offset dies in decay_s). A
    // ramp, not a reset -- the stale-data branch's "no step transients"
    // intent is kept. apex_hold_decay_s = 0.0 disables (the pre-decay
    // behaviour). Runs only when a channel is enabled and an offset is
    // nonzero, so the default path stays bit-identical.
    double apex_hold_grace_s_;
    double apex_hold_decay_s_;
    double apex_last_fire_s_{-1.0};
    double apex_decay_prev_s_{-1.0};
    bool apex_decay_warned_{false};

    // Open-loop Ackermann pair; see gamma_openloop(). All rad except dir.
    double gamma_acker_in_;
    double gamma_acker_out_;
    // +1 = inner pair RIGHT (B,C) = lean RIGHT = CW/right turn (kappa < 0);
    // -1 mirrors; 0 off. Settled empirically 2026-08-20 (log s88) and by
    // camber_roll.py's "lambda > 0 leans right" comment.
    double gamma_acker_dir_;
    double gamma_acker_limit_;  // clamp on the open-loop term alone
    int gamma_acker_ramp_ticks_;
    // Closed-loop camber (Stage 3 task 6; design log S232, numbers S235):
    // lambda on the SAME L/R pattern, driven by the shared yaw reference.
    //   lam_cmd = -sign(turn_rate)*ff + k_acker_yaw*yaw_err + d_acker_yaw*wz
    // ff > 0 ENABLES the loop and replaces dir/in/out (setting both is fatal
    // at startup). Anti-windup is the reference's own turn_err_limit_. Rad.
    double gamma_acker_ff_;
    double k_acker_yaw_;
    double d_acker_yaw_;
    // Magnitude range [min, hi]: the measured proportional region, R ~3.0 m
    // at 5 deg to 2.3 m at 15 deg (S235). gamma_acker_limit_ stays the hard
    // clamp above.
    double gamma_acker_min_;
    double gamma_acker_hi_;
    // Ticks since the stride loop started, for the entry ramp. Counted in
    // apply_row so the settle (yaw_ref_set_ false) never advances it.
    int acker_ramp_count_{0};

    // STANCE-PEAK DIP on the open-loop camber term (log S205/S206, Open
    // Issue #15). The ABAD demand peaks 30-40 ms after touchdown and crosses
    // its 44.25 N.m ceiling there on the loaded leg -- a ~10 ms spike, clipped
    // SILENTLY, on 40-50% of stance events at lambda 15. This scales the
    // commanded camber toward zero inside a raised-cosine window
    // [dip_t0, dip_t1] ms after a DEBOUNCED touchdown, so the ABAD yields at
    // the load peak by command instead of by clip. 0.0 = off, bit-identical.
    // Re-arms only after >= dip_rearm_ms of stable flight, because the raw
    // contact flag fragments stance into ~60 ms pieces (#22) and a window that
    // re-fired on every fragment would dip the whole stance.
    double gamma_acker_dip_;          // fraction of the camber term removed at the window centre
    int gamma_acker_dip_t0_ms_;       // window start, ms after debounced touchdown
    int gamma_acker_dip_t1_ms_;       // window end
    int gamma_acker_dip_rearm_ms_;    // stable flight required before the next touchdown counts
    std::array<int, 4> dip_since_td_ticks_{{-1, -1, -1, -1}};   // -1 = not in an armed stance
    std::array<int, 4> dip_flight_ticks_{{0, 0, 0, 0}};
    std::array<bool, 4> dip_prev_stable_{{false, false, false, false}};
    void dip_tick();                  // one 1 ms tick of the per-leg touchdown clocks

    // STANCE-PEAK YIELD (log S213 S4 / S220). The dip (above) scaled the
    // command toward ZERO lean and made everything worse, because at the load
    // peak the loaded leg already sits PAST its command (signed error -1.3
    // deg, n = 441): the dip moved the command further from where the leg
    // was. The yield blends the commanded gamma toward the MEASURED gamma
    // inside the same window, so the proportional term relaxes toward zero
    // regardless of which side of the command the leg is on. No sign to get
    // wrong. Shares the dip's window and touchdown clocks. 0.0 = off.
    double gamma_acker_yield_;
    double measured_gamma(int leg_index) const;

    // Steering; see the block comment above steer_command().
    double k_steer_;
    double steer_offset_;   // rad
    double steer_limit_;    // rad, clamp on the total beta perturbation
    bool steer_prepose_;
    double k_steer_yaw_;
    double d_steer_yaw_;

    // Commanded turn rate, rad/s. Positive is a LEFT turn, following
    // steer_offset's measured sense (+offset turns left) and the right-handed
    // world yaw the IMU reports.
    double turn_rate_;

    // Anti-runaway on the reference, rad. See advance_yaw_ref().
    double turn_err_limit_;

    // Ticks to hold the stance after the trigger, before the stride starts.
    // In experiment mode the same /trigger that starts this gait also deletes
    // SUPPORT_BOX, so the robot is settling onto its legs at that instant.
    // Striding through the settle would corrupt the first touchdown.
    //
    // Raised 1000 -> 2500 on 2026-08-08. 1 s was marginal: per-stride hop data
    // across eight ramp runs shows the opening strides frequently below par and
    // then recovering, and in the worst case the robot took FIVE strides
    // (~1.34 s) to start hopping at all -- 0, 0, 0, 0, 0, 3.4, 15.0, 56.2% --
    // which failed the run's validity gate outright. Even a healthy run showed
    // a one-to-two stride transient (21.4, 55.1, then 70s). The cost is ~1.5 s
    // of extra sim time per run, against a 9.57 s pass; the benefit is fewer
    // discarded runs, and the hop segment IS the gate.
    int settle_ticks_;

    // Phase 5 step 1: hold the standing pose with the STANCE (leg-frame)
    // impedance rather than the flight gains, so the virtual spring can be
    // probed by pushing the body before anything hops.
    bool hold_stance_;

    // Live gain retuning. The impedance gains are read every tick, so a
    // callback that updates the members is enough to change them without a
    // restart -- which is what the k_radial sweep needs (log S146): restarting
    // between arms folds the legs to the 17 deg stop and the next arm spends
    // its dwell recovering.
    rclcpp::node_interfaces::OnSetParametersCallbackHandle::SharedPtr param_cb_;
    rcl_interfaces::msg::SetParametersResult on_set_params(
        const std::vector<rclcpp::Parameter>& params);
};

GslipPronkNode::GslipPronkNode()
    : Node("gslip_pronk"),
      // Order here must match DECLARATION order -- the contact members are
      // declared above trigger_, and C++ initializes in declaration order
      // regardless of what this list says.
      contact_gated_gains_(false),
      contact_debounce_(3),
      contact_timeout_s_(0.25),
      last_contact_stamp_(0.0),
      contact_stale_warned_(false),
      event_sched_(false),
      event_snap_limit_s_(0.030),
      event_blend_ticks_(20),
      event_snap_per_stride_(1),
      event_arm_strides_(0),  // Tier 0's decision output (log S92)
      stance_max_overrun_ratio_(1.5),
      event_forward_only_(false),
      slave_stance_(false),
      slave_v_source_("fixed"),
      // v-tilde 0.70 * sqrt(g * l0), the v070 template's own design
      // point: slaving at the template's design speed should reproduce
      // template-like rolling, which is the mechanism-validation arm.
      slave_v_fixed_(1.187),
      ekf_timeout_s_(0.05),
      push_sync_(false),
      push_sync_quorum_(4),
      push_sync_max_hold_s_(0.080),
      push_sync_arm_strides_(5),
      couple_gain_(0.0),
      couple_clamp_(0.05),
      stance_label_shift_s_(0.0),
      stance_label_duty_(0.0),
      stance_sweep_scale_(1.0),
      contact_align_rows_(0),
      contact_sweep_rows_(0),
      contact_sweep_scale_(1.0),
      contact_ramp_rows_(0),
      trigger_(false),
      sim_(false),
      k_radial_(8941.0),
      k_tangential_(1200.0),   // ADOPTED S300; aligned with the launch
                               // default (was 900 vs launch 600 -- the
                               // documented divergence trap, now closed)
      k_lateral_(7500.0),
      b_radial_(0.0),
      b_tangential_(30.0),
      b_lateral_(60.0),
      clock_ff_scale_(0.0),
      clock_ff_phase_("stance"),
      f_lateral_(0.0),
      f_lateral_front_only_(false),
      // #19 step 2 (2026-08-24): the launch/ctor default IS the config of
      // record, 7150/115.8 (SS103-109). It was left at the rejected
      // 12000/150 design point for four days and silently corrupted every
      // campaign that did not pass the gains explicitly (kt_sweep, S152).
      k_flight_(7150.0),
      b_flight_(115.8),
      standup_ticks_(2000),
      // Default OFF. The reasoning is sound for the model -- l0 is the rest
      // length and l(t) is an output -- but in the robot it flipped the
      // machine: measured compression already reaches 71-75 deg, so
      // referencing from 100 deg rest gives 29 deg of compression, about
      // 492 N per leg or 6.7 body weights against the model's 3.64, and the
      // resulting push threw it over (145 deg tilt, legs folded past their
      // 17 deg limit).
      //
      // The discrepancy is not in this reference choice. It is that the robot
      // is nowhere near the fixed point the template was solved for: that
      // fixed point assumes 2.035 m/s of forward travel, and the robot is
      // essentially hopping in place. Touchdown velocity, and therefore
      // compression, are simply not the model's.
      //
      // (Initialised here, out of narrative order, because it is DECLARED
      // before the attitude gains and -Wreorder tracks declaration order.)
      spring_rest_reference_(false),
      // Gentle. At k_roll 0.6 / k_yaw 0.4 with a 12 deg clamp the correction
      // saturated -- measured gamma reached 15-17 deg -- and while it did halve
      // the yaw drift and even out the contact balance, tilting the legs that
      // far cost the vertical push: flight fell from 34% to 8.9% and the leg
      // phase correlation from 0.92-0.98 to 0.70-0.91. The authority has to
      // stay small enough not to disturb the hop it is stabilising.
      k_roll_(0.25),
      d_roll_(0.03),
      // HEADING HOLD OFF BY DEFAULT, 2026-08-22 (S163, S168). The yaw term
      // steers by differential front/rear camber and was SATURATED at the 5 deg
      // gamma_limit -- demanding maximum lean and still drifting -5.8 deg/s.
      // With it off: yaw -0.86 deg/s (6.7x less), straightness 0.865 -> 0.987,
      // same speed, and the front/rear camber projection goes -5.179 -> +0.005
      // deg. Adopted on Alex's decision at n = 1 plus S163's banked n = 4.
      //
      // ⚠ THIS REMOVES THE HEADING HOLD ENTIRELY. The robot is straighter
      // because it stopped fighting, not because it is corrected: -0.86 deg/s
      // is uncorrected and unbounded, ~52 deg over a minute. Commanded turning
      // is unaffected (steer_offset / k_steer_yaw and the Ackermann camber
      // channel are separate). Stage 3/4 will need a hold back -- the intended
      // answer is gamma_yaw_limit ~0.0175 (S89 C2, P-M-2), which is UNTESTED:
      // its one run failed the gait gate at 24.5%% flight.
      //
      // P-M-1..P-M-3 remain REGISTERED AND UNSCORED at n >= 5.
      k_yaw_(0.0),
      d_yaw_(0.0),
      gamma_limit_(5.0 / 180.0 * M_PI),
      gamma_yaw_limit_(0.0),
      k_pitch_(-0.30),   // ADOPTED S300 with k_tangential (was 0.0)
      d_pitch_(0.0),
      // 3 deg. The operating theta is ~90-100 deg and the five-bar folds
      // at 17; 3 deg of differential leg length is a large body-pitch
      // authority (the pairs are 0.51 m apart) while staying an order of
      // magnitude clear of anything the linkage cares about.
      pitch_limit_(3.0 / 180.0 * M_PI),
      // Apex beta feedback: OFF. The gains are the plant-point deadbeat row
      // (examples/gslip/stage2b_deadbeat_at_plant.py, rcond 0.2); the star
      // values are that fixed point. Loading them as defaults costs nothing
      // while apex_fb_gain_ is 0.0 and means turning the channel on is one
      // parameter, not five.
      apex_fb_gain_(0.0),
      apex_k_vx_(-0.5485),
      apex_k_h_(0.6119),
      apex_vx_star_(0.3106),
      apex_h_star_(0.2886),
      // 4 deg. The plant-point beta* is 86.24 deg and the template's own
      // sweep is +-9.5 deg at v070, so a 4 deg correction is a real lever
      // without being a step the leg cannot track in one flight.
      apex_beta_limit_(4.0 / 180.0 * M_PI),
      apex_odom_topic_("/sim/base_odom"),
      // Apex differential camber: OFF. Gains are K's lam_l row at the S263
      // plant orbit (see the header block); loaded as defaults for the same
      // reason as the beta row's -- enabling is one parameter, not four.
      apex_dc_gain_(0.0),
      apex_dc_k_vy_(-1.054120),
      apex_dc_k_rho_(-5.769254),
      apex_dc_k_drho_(-0.168636),
      // 4 deg, the beta row's discipline. Note k_rho alone reaches it at
      // 0.7 deg of roll, so the clamp IS the working regime, not a backstop;
      // the per-orbit gain sweep (the S57 rerun this channel awaits) owns
      // the final value.
      apex_dc_limit_(4.0 / 180.0 * M_PI),
      // Grace 0.8 s ~ 3 strides at v070's 0.2662 s: a healthy pronk apexes
      // every stride, so three missed strides means flight is GONE, not
      // late. Decay 0.5 s ~ 2 strides from full scale to zero.
      apex_hold_grace_s_(1.3),   // S304 (was 0.8): the fixed detector's
                                 // healthy gap texture rides through;
                                 // a true S268 stall still bleeds in 1.8 s
      apex_hold_decay_s_(0.5),
      gamma_acker_in_(0.0),
      gamma_acker_out_(0.0),
      gamma_acker_dir_(0.0),
      // 20 deg: above the 15 deg the Stage 3 sweep tops out at, well under
      // the +-30 deg the model's u_limits allow, and far from folding a leg.
      gamma_acker_limit_(20.0 / 180.0 * M_PI),
      // 500 ms entry ramp, mirroring camber_roll.py's lean window: a step
      // into a stiff position loop at 1 kHz is a torque spike.
      gamma_acker_ramp_ticks_(500),
      gamma_acker_ff_(0.0),
      k_acker_yaw_(0.0),
      d_acker_yaw_(0.0),
      gamma_acker_min_(5.0 / 180.0 * M_PI),
      gamma_acker_hi_(15.0 / 180.0 * M_PI),
      gamma_acker_dip_(0.0),
      gamma_acker_dip_t0_ms_(20),
      gamma_acker_dip_t1_ms_(60),
      gamma_acker_dip_rearm_ms_(30),
      gamma_acker_yield_(0.0),
      k_steer_(0.0),
      steer_offset_(0.0),
      // 8 deg. Sized above the 5 deg the authority estimate calls for, so the
      // clamp does not silently cap the first experiments, but well inside the
      // sweep the template already commands (+-18 deg at the top rung) so a
      // runaway feedback term cannot fold a leg.
      steer_limit_(8.0 / 180.0 * M_PI),
      steer_prepose_(false),
      k_steer_yaw_(0.0),
      d_steer_yaw_(0.0),
      turn_rate_(0.0),
      // 90 deg. Wide enough never to bite while the loop is keeping up -- a
      // heading-hold run that is 90 deg off has already failed -- and tight
      // enough to stop the reference lapping the robot when it is not.
      turn_err_limit_(M_PI / 2.0),
      settle_ticks_(2500),
      hold_stance_(false)
{
    RCLCPP_INFO(this->get_logger(), "G-SLIP pronk controller starting");

    this->get_parameter_or("use_sim_time", sim_, false);

    const std::string default_template =
        ament_index_cpp::get_package_share_directory("corgi_force_control")
        + "/config/gslip_pronk_template_v070.csv";  // #19 step 2: the
        // default template is the template of record (was the pre-v070 one,
        // the same silent-default failure mode as the gains above).
    std::string template_path =
        this->declare_parameter<std::string>("template_path", default_template);
    // Launch files pass an empty string to mean "use the installed default"
    // rather than having to repeat the share-directory lookup.
    if (template_path.empty()) template_path = default_template;

    k_radial_ = this->declare_parameter<double>("k_radial", k_radial_);
    k_tangential_ = this->declare_parameter<double>("k_tangential", k_tangential_);
    k_lateral_ = this->declare_parameter<double>("k_lateral", k_lateral_);
    b_radial_ = this->declare_parameter<double>("b_radial", b_radial_);
    b_tangential_ = this->declare_parameter<double>("b_tangential", b_tangential_);
    b_lateral_ = this->declare_parameter<double>("b_lateral", b_lateral_);
    f_lateral_ = this->declare_parameter<double>("f_lateral", f_lateral_);
    f_lateral_front_only_ =
        this->declare_parameter<bool>("f_lateral_front_only", f_lateral_front_only_);
    k_flight_ = this->declare_parameter<double>("k_flight", k_flight_);
    b_flight_ = this->declare_parameter<double>("b_flight", b_flight_);
    clock_ff_scale_ =
        this->declare_parameter<double>("clock_ff_scale", clock_ff_scale_);
    clock_ff_phase_ =
        this->declare_parameter<std::string>("clock_ff_phase", clock_ff_phase_);

    // Announce the leg-frame gains once, at startup.
    //
    // WHY. k_tangential had no log line at all: it was declared here and used
    // at `cmd->kz = k_tangential_` with nothing in between, so
    // repeat_gain_regime.sh -- whose four engagement asserts are all greps --
    // had nothing to grep for, and its own comment said the parameter "must be
    // verified from the DATA instead". S138 and S146 each cost a whole
    // campaign to an unverified engagement; finding out in run 1 rather than
    // after ten is the point.
    //
    // NOTE the parameter callback is registered BELOW this point, so these
    // gains never produce a "LIVE GAIN SET" line at startup -- only runtime
    // `ros2 param set` does. That is why this explicit line is needed.
    RCLCPP_WARN(this->get_logger(),
                "LEG-FRAME GAINS: k_radial=%.1f k_tangential=%.1f "
                "k_lateral=%.1f | b_radial=%.1f b_tangential=%.1f "
                "b_lateral=%.1f | k_flight=%.1f b_flight=%.1f",
                k_radial_, k_tangential_, k_lateral_, b_radial_,
                b_tangential_, b_lateral_, k_flight_, b_flight_);
    // Config of record since 2026-08-30 (S300): 1200.0. Ctor and launch
    // defaults now AGREE (the 900-vs-600 divergence trap is closed).
    if (std::fabs(k_tangential_ - 1200.0) > 1e-6) {
        RCLCPP_WARN(this->get_logger(),
                    "K_TANGENTIAL OVERRIDDEN: %.1f (config of record "
                    "1200.0, S300). This line is PROOF OF INTENT ONLY -- "
                    "it proves the parameter was READ, not that it reached "
                    "the impedance law. S138's apex channel printed its "
                    "parameters faithfully for ten runs and never fired. "
                    "Verify the action with scripts/diag/kt_engagement.py.",
                    k_tangential_);
    }
    standup_ticks_ = this->declare_parameter<int>("standup_ticks", standup_ticks_);
    hold_stance_ = this->declare_parameter<bool>("hold_stance", hold_stance_);
    param_cb_ = this->add_on_set_parameters_callback(
        std::bind(&GslipPronkNode::on_set_params, this, std::placeholders::_1));
    contact_gated_gains_ = this->declare_parameter<bool>(
        "contact_gated_gains", contact_gated_gains_);
    contact_debounce_ = this->declare_parameter<int>(
        "contact_debounce", contact_debounce_);
    contact_timeout_s_ = this->declare_parameter<double>(
        "contact_timeout_s", contact_timeout_s_);
    stance_label_shift_s_ = this->declare_parameter<double>(
        "stance_label_shift_s", stance_label_shift_s_);
    stance_label_duty_ = this->declare_parameter<double>(
        "stance_label_duty", stance_label_duty_);
    stance_sweep_scale_ = this->declare_parameter<double>(
        "stance_sweep_scale", stance_sweep_scale_);
    contact_align_rows_ = this->declare_parameter<int>(
        "contact_align_rows", contact_align_rows_);
    contact_sweep_rows_ = this->declare_parameter<int>(
        "contact_sweep_rows", contact_sweep_rows_);
    contact_sweep_scale_ = this->declare_parameter<double>(
        "contact_sweep_scale", contact_sweep_scale_);
    contact_ramp_rows_ = this->declare_parameter<int>(
        "contact_ramp_rows", contact_ramp_rows_);
    settle_ticks_ = this->declare_parameter<int>("settle_ticks", settle_ticks_);
    k_roll_ = this->declare_parameter<double>("k_roll", k_roll_);
    d_roll_ = this->declare_parameter<double>("d_roll", d_roll_);
    k_yaw_ = this->declare_parameter<double>("k_yaw", k_yaw_);
    d_yaw_ = this->declare_parameter<double>("d_yaw", d_yaw_);
    gamma_limit_ = this->declare_parameter<double>("gamma_limit", gamma_limit_);
    gamma_yaw_limit_ =
        this->declare_parameter<double>("gamma_yaw_limit", gamma_yaw_limit_);
    k_pitch_ = this->declare_parameter<double>("k_pitch", k_pitch_);
    d_pitch_ = this->declare_parameter<double>("d_pitch", d_pitch_);
    pitch_limit_ = this->declare_parameter<double>("pitch_limit", pitch_limit_);
    apex_fb_gain_ =
        this->declare_parameter<double>("apex_fb_gain", apex_fb_gain_);
    apex_k_vx_ = this->declare_parameter<double>("apex_k_vx", apex_k_vx_);
    apex_k_h_ = this->declare_parameter<double>("apex_k_h", apex_k_h_);
    apex_vx_star_ =
        this->declare_parameter<double>("apex_vx_star", apex_vx_star_);
    apex_h_star_ = this->declare_parameter<double>("apex_h_star", apex_h_star_);
    apex_beta_limit_ =
        this->declare_parameter<double>("apex_beta_limit", apex_beta_limit_);
    apex_odom_topic_ = this->declare_parameter<std::string>(
        "apex_odom_topic", apex_odom_topic_);
    apex_dc_gain_ =
        this->declare_parameter<double>("apex_dc_gain", apex_dc_gain_);
    apex_dc_k_vy_ =
        this->declare_parameter<double>("apex_dc_k_vy", apex_dc_k_vy_);
    apex_dc_k_rho_ =
        this->declare_parameter<double>("apex_dc_k_rho", apex_dc_k_rho_);
    apex_dc_k_drho_ =
        this->declare_parameter<double>("apex_dc_k_drho", apex_dc_k_drho_);
    apex_dc_limit_ =
        this->declare_parameter<double>("apex_dc_limit", apex_dc_limit_);
    apex_hold_grace_s_ = this->declare_parameter<double>(
        "apex_hold_grace_s", apex_hold_grace_s_);
    apex_hold_decay_s_ = this->declare_parameter<double>(
        "apex_hold_decay_s", apex_hold_decay_s_);
    gamma_acker_in_ =
        this->declare_parameter<double>("gamma_acker_in", gamma_acker_in_);
    gamma_acker_out_ =
        this->declare_parameter<double>("gamma_acker_out", gamma_acker_out_);
    gamma_acker_dir_ =
        this->declare_parameter<double>("gamma_acker_dir", gamma_acker_dir_);
    gamma_acker_ff_ =
        this->declare_parameter<double>("gamma_acker_ff", gamma_acker_ff_);
    k_acker_yaw_ =
        this->declare_parameter<double>("k_acker_yaw", k_acker_yaw_);
    d_acker_yaw_ =
        this->declare_parameter<double>("d_acker_yaw", d_acker_yaw_);
    gamma_acker_min_ =
        this->declare_parameter<double>("gamma_acker_min", gamma_acker_min_);
    gamma_acker_hi_ =
        this->declare_parameter<double>("gamma_acker_hi", gamma_acker_hi_);
    if (gamma_acker_ff_ > 0.0 && gamma_acker_dir_ != 0.0) {
        RCLCPP_FATAL(this->get_logger(),
                     "gamma_acker_ff (closed-loop) and gamma_acker_dir "
                     "(open-loop) are both set -- ambiguous camber command, "
                     "refusing to start (S128's silent-config lesson).");
        throw std::runtime_error("ambiguous camber configuration");
    }
    gamma_acker_limit_ =
        this->declare_parameter<double>("gamma_acker_limit", gamma_acker_limit_);
    gamma_acker_ramp_ticks_ = this->declare_parameter<int>(
        "gamma_acker_ramp_ticks", gamma_acker_ramp_ticks_);
    gamma_acker_dip_ =
        this->declare_parameter<double>("gamma_acker_dip", gamma_acker_dip_);
    gamma_acker_dip_t0_ms_ = this->declare_parameter<int>(
        "gamma_acker_dip_t0_ms", gamma_acker_dip_t0_ms_);
    gamma_acker_dip_t1_ms_ = this->declare_parameter<int>(
        "gamma_acker_dip_t1_ms", gamma_acker_dip_t1_ms_);
    gamma_acker_dip_rearm_ms_ = this->declare_parameter<int>(
        "gamma_acker_dip_rearm_ms", gamma_acker_dip_rearm_ms_);
    gamma_acker_dip_ = std::max(0.0, std::min(1.0, gamma_acker_dip_));
    gamma_acker_yield_ =
        this->declare_parameter<double>("gamma_acker_yield", gamma_acker_yield_);
    gamma_acker_yield_ = std::max(0.0, std::min(1.0, gamma_acker_yield_));
    k_steer_ = this->declare_parameter<double>("k_steer", k_steer_);
    steer_offset_ = this->declare_parameter<double>("steer_offset", steer_offset_);
    steer_limit_ = this->declare_parameter<double>("steer_limit", steer_limit_);
    steer_prepose_ = this->declare_parameter<bool>("steer_prepose", steer_prepose_);
    k_steer_yaw_ = this->declare_parameter<double>("k_steer_yaw", k_steer_yaw_);
    d_steer_yaw_ = this->declare_parameter<double>("d_steer_yaw", d_steer_yaw_);
    turn_rate_ = this->declare_parameter<double>("turn_rate", turn_rate_);
    turn_err_limit_ =
        this->declare_parameter<double>("turn_err_limit", turn_err_limit_);
    spring_rest_reference_ =
        this->declare_parameter<bool>("spring_rest_reference", spring_rest_reference_);
    event_sched_ = this->declare_parameter<bool>("event_sched", event_sched_);
    event_snap_limit_s_ = this->declare_parameter<double>(
        "event_snap_limit_s", event_snap_limit_s_);
    event_blend_ticks_ = this->declare_parameter<int>(
        "event_blend_ticks", event_blend_ticks_);
    event_snap_per_stride_ = this->declare_parameter<int>(
        "event_snap_per_stride", event_snap_per_stride_);
    event_arm_strides_ = this->declare_parameter<int>(
        "event_arm_strides", event_arm_strides_);
    stance_max_overrun_ratio_ = this->declare_parameter<double>(
        "stance_max_overrun_ratio", stance_max_overrun_ratio_);
    event_forward_only_ = this->declare_parameter<bool>(
        "event_forward_only", event_forward_only_);
    slave_stance_ = this->declare_parameter<bool>("slave_stance", slave_stance_);
    slave_v_source_ = this->declare_parameter<std::string>(
        "slave_v_source", slave_v_source_);
    slave_v_fixed_ = this->declare_parameter<double>(
        "slave_v_fixed", slave_v_fixed_);
    ekf_timeout_s_ = this->declare_parameter<double>(
        "ekf_timeout_s", ekf_timeout_s_);
    push_sync_ = this->declare_parameter<bool>("push_sync", push_sync_);
    push_sync_quorum_ = this->declare_parameter<int>(
        "push_sync_quorum", push_sync_quorum_);
    push_sync_max_hold_s_ = this->declare_parameter<double>(
        "push_sync_max_hold_s", push_sync_max_hold_s_);
    push_sync_arm_strides_ = this->declare_parameter<int>(
        "push_sync_arm_strides", push_sync_arm_strides_);
    if (push_sync_ && !slave_stance_) {
        RCLCPP_ERROR(this->get_logger(),
                     "PUSH SYNC REFUSED: requires slave_stance (it gates "
                     "the slaved sweep's start). Forced OFF.");
        push_sync_ = false;
    }
    if (push_sync_ && (push_sync_quorum_ < 2 || push_sync_quorum_ > 4)) {
        RCLCPP_ERROR(this->get_logger(),
                     "PUSH SYNC REFUSED: quorum %d outside 2..4. Forced "
                     "OFF.", push_sync_quorum_);
        push_sync_ = false;
    }
    couple_gain_ = this->declare_parameter<double>("couple_gain", couple_gain_);
    couple_clamp_ =
        this->declare_parameter<double>("couple_clamp", couple_clamp_);
    if (couple_gain_ != 0.0 && !event_sched_) {
        RCLCPP_ERROR(this->get_logger(),
                     "PHASE COUPLING REFUSED: couple_gain=%.4f requires "
                     "event_sched. Forced OFF.", couple_gain_);
        couple_gain_ = 0.0;
    }
    std::string lut_path = this->declare_parameter<std::string>(
        "ltheta_lut_path", std::string(""));
    // Launch files pass an empty string to mean "the installed default",
    // same idiom as template_path.
    if (lut_path.empty())
        lut_path =
            ament_index_cpp::get_package_share_directory("corgi_force_control")
            + "/config/gslip_ltheta_lut.csv";

    if (slave_stance_ && !event_sched_) {
        RCLCPP_ERROR(this->get_logger(),
                     "SLAVE STANCE REFUSED: requires event_sched (per-leg "
                     "clocks + touchdown events are its substrate). Forced "
                     "OFF.");
        slave_stance_ = false;
    }
    if (slave_stance_ && stance_sweep_scale_ != 1.0) {
        RCLCPP_ERROR(this->get_logger(),
                     "SLAVE STANCE REFUSED: stance_sweep_scale=%.3f is the "
                     "superseded open-loop version of the same idea. Forced "
                     "OFF.", stance_sweep_scale_);
        slave_stance_ = false;
    }
    if (slave_stance_) {
        lut_ok_ = load_ltheta_lut(lut_path);
        if (!lut_ok_)
            RCLCPP_ERROR(this->get_logger(),
                         "SLAVE STANCE REFUSED: L(theta) LUT unusable at "
                         "'%s'.", lut_path.c_str());
        if (slave_v_source_ != "fixed" && slave_v_source_ != "ekf") {
            RCLCPP_ERROR(this->get_logger(),
                         "SLAVE STANCE REFUSED: slave_v_source='%s' (need "
                         "fixed|ekf).", slave_v_source_.c_str());
            lut_ok_ = false;
        }
        if (slave_v_source_ == "ekf") {
            ekf_sub_ = this->create_subscription<nav_msgs::msg::Odometry>(
                "ekf", 100,
                std::bind(&GslipPronkNode::ekf_cb, this,
                          std::placeholders::_1));
        }
    }
    // The apex channel needs the same topic for a different reason, and the
    // block above only subscribes when Tier 3 slaving is on. Without this it
    // runs INERT while announcing itself -- which is exactly what happened for
    // ten Webots runs (log S138).
    if ((apex_fb_gain_ != 0.0 || apex_dc_gain_ != 0.0) && !ekf_sub_) {
        // WHICH TOPIC. /ekf is published by corgi_fusion_node, which the
        // menger_acker campaign harness does NOT launch -- it starts only
        // Corgi_launch.py and gslip_pronk.launch.py. So on /ekf this channel
        // starves in every campaign run, which is how it managed ten inert
        // runs (log S138).
        //
        // /sim/base_odom is Webots GROUND TRUTH and is always available in
        // sim. Using it makes the channel testable, at the cost of feeding the
        // controller privileged information: any result obtained this way is
        // an UPPER BOUND on what the channel can do with a real estimator, and
        // must be reported as such. Hardware runs must set this to /ekf and
        // launch the estimator.
        RCLCPP_WARN(this->get_logger(),
                    "APEX BETA FB source: '%s'%s", apex_odom_topic_.c_str(),
                    apex_odom_topic_ == "/sim/base_odom"
                        ? "  <-- GROUND TRUTH. Sim only. Results are an upper "
                          "bound, not an estimator-in-the-loop result."
                        : "");
        ekf_sub_ = this->create_subscription<nav_msgs::msg::Odometry>(
            apex_odom_topic_, 100,
            std::bind(&GslipPronkNode::ekf_cb, this, std::placeholders::_1));
    }

    // Refusal matrix (handover, Tier 1). Refuse = disable + grep-able ERROR,
    // the stance_label_duty pattern: the robot stays runnable on the global
    // clock, and the harness's engagement assert catches the absence.
    if (event_sched_ && contact_gated_gains_) {
        RCLCPP_ERROR(this->get_logger(),
                     "EVENT SCHED REFUSED: mutually exclusive with "
                     "contact_gated_gains (that design gates half of one "
                     "phase description -- see the post-mortem above; the "
                     "scheduler is its principled replacement, not a "
                     "companion). event_sched forced OFF.");
        event_sched_ = false;
    }
    if (event_sched_ && stance_label_shift_s_ != 0.0) {
        RCLCPP_ERROR(this->get_logger(),
                     "EVENT SCHED REFUSED: stance_label_shift_s=%.3f is a "
                     "global open-loop correction of the same phase error "
                     "the snap corrects per leg -- running both "
                     "double-corrects. event_sched forced OFF.",
                     stance_label_shift_s_);
        event_sched_ = false;
    }
    if (event_sched_ && stance_label_duty_ != 0.0) {
        // Orthogonal (duty reshapes the table the scheduler plays), allowed;
        // logged so no capture is ever puzzled over.
        RCLCPP_WARN(this->get_logger(),
                    "EVENT SCHED + stance_label_duty=%.3f: allowed "
                    "(orthogonal -- duty reshapes the table, the scheduler "
                    "re-times it), recording the combination.",
                    stance_label_duty_);
    }

    if (sim_) {
        RCLCPP_INFO(this->get_logger(), "Waiting for Webots clock...");
        while (rclcpp::ok()) {
            rclcpp::spin_some(this->get_node_base_interface());
            if (this->now().seconds() > 0.0) {
                RCLCPP_INFO(this->get_logger(), "Clock synced! Sim Time: %.2f",
                            this->now().seconds());
                break;
            }
            rclcpp::sleep_for(std::chrono::milliseconds(100));
        }
    } else {
        RCLCPP_INFO(this->get_logger(), "Real hardware mode: using system wall clock.");
    }

    imp_cmd_pub_ = this->create_publisher<corgi_msgs::msg::ImpedanceCmdStamped>(
        "impedance/command", 1000);
    trigger_sub_ = this->create_subscription<corgi_msgs::msg::TriggerStamped>(
        "trigger", 1000,
        std::bind(&GslipPronkNode::trigger_cb, this, std::placeholders::_1));
    motor_state_sub_ = this->create_subscription<corgi_msgs::msg::MotorStateStamped>(
        "motor/state", 1000,
        std::bind(&GslipPronkNode::motor_state_cb, this, std::placeholders::_1));
    imu_sub_ = this->create_subscription<corgi_msgs::msg::ImuStamped>(
        "imu", 1000,
        std::bind(&GslipPronkNode::imu_cb, this, std::placeholders::_1));
    contact_sub_ = this->create_subscription<corgi_msgs::msg::SimLegContactStamped>(
        "sim/leg_contact", 1000,
        std::bind(&GslipPronkNode::contact_cb, this, std::placeholders::_1));

    if (contact_gated_gains_) {
        // Say so loudly. This changes which stiffness matrix each leg sees, so
        // a run made with it on is not comparable to the existing campaigns.
        RCLCPP_WARN(this->get_logger(),
                    "CONTACT-GATED GAINS ON (debounce %d, timeout %.2fs). "
                    "Gain regime follows measured per-leg contact, not the "
                    "template phase. Results are NOT comparable to prior runs.",
                    contact_debounce_, contact_timeout_s_);
        RCLCPP_WARN(this->get_logger(),
                    "Source is sim/leg_contact, which does not exist on "
                    "hardware; if it never arrives the gate falls back to the "
                    "template phase and says so.");
    }

    imp_cmd_modules_ = {
        &imp_cmd_.module_a,
        &imp_cmd_.module_b,
        &imp_cmd_.module_c,
        &imp_cmd_.module_d
    };

    if (!load_template(template_path)) {
        RCLCPP_FATAL(this->get_logger(),
                     "Could not load the stride template from '%s'. Generate it with "
                     "LegWheel: uv run python examples/gslip/export_pronk_csv.py",
                     template_path.c_str());
        throw std::runtime_error("missing stride template");
    }

    // The spring is uncompressed at touchdown, so the template's maximum
    // theta is the rest extension.
    theta_rest_ = template_.front().theta;
    for (const auto& row : template_) theta_rest_ = std::max(theta_rest_, row.theta);

    RCLCPP_INFO(this->get_logger(),
                "Loaded %zu template rows (%.4f s stride), k_radial=%.0f N/m per leg",
                template_.size(), template_.back().t, k_radial_);
    RCLCPP_INFO(this->get_logger(),
                "Radial reference: %s (rest theta %.2f deg)",
                spring_rest_reference_ ? "SPRING REST (constant)"
                                       : "template trajectory",
                theta_rest_ * 180.0 / M_PI);

    // The clocked feedforward, announced AFTER the template is loaded because
    // its rate is derived from that template -- which is the whole point.
    //
    // S164 priced the missing term at 8.0 N.m/motor. That number came from the
    // v~1.20 DEFAULT template (6.556 rad/s); at the v070 config of record the
    // clock runs at 3.010 rad/s and the term is 3.2 N.m/motor. Printing the
    // derived N.m here is what makes that visible in run 1 instead of after a
    // campaign -- same lesson as S159's template_path default.
    //
    // PROOF OF INTENT ONLY. It proves the parameter was READ and the rate was
    // derived, NOT that the term reached the impedance law. Verify the action
    // with scripts/diag/clock_ff_engagement.py, which regresses the driver's
    // t_ff against b_tangential*dbeta_ref*L(theta)^2 and wants slope +1.
    {
        const double L_gait = 0.265630;   // hip->contact at theta 85.4 deg, S151
        const double nm_motor =
            0.5 * b_tangential_ * clock_ff_scale_ * clock_rate_stance_
            * L_gait * L_gait;
        RCLCPP_WARN(this->get_logger(),
                    "CLOCK FEEDFORWARD: scale=%.3f phase=%s "
                    "rate_stance=%.4f rate_flight=%.4f rad/s -> %.2f N.m/motor "
                    "stance (%s)",
                    clock_ff_scale_, clock_ff_phase_.c_str(),
                    clock_rate_stance_, clock_rate_flight_, nm_motor,
                    clock_ff_scale_ == 0.0
                        ? "OFF -- damps to zero, the pre-S164 behaviour"
                        : "ON -- Lu & Lin eq 11 D term");
    }
    if (clock_ff_phase_ != "stance" && clock_ff_phase_ != "both") {
        RCLCPP_FATAL(this->get_logger(),
                     "clock_ff_phase must be 'stance' or 'both', got '%s'",
                     clock_ff_phase_.c_str());
        throw std::runtime_error("bad clock_ff_phase");
    }
}

void GslipPronkNode::contact_cb(
        const corgi_msgs::msg::SimLegContactStamped::SharedPtr msg) {
    const bool raw[4] = {
        msg->module_a.contact, msg->module_b.contact,
        msg->module_c.contact, msg->module_d.contact,
    };
    // Debounce. Contact chatters at touchdown, and an undebounced gate would
    // flip the commanded stiffness by 8x between consecutive control ticks --
    // which is a bigger disturbance than the mismatch being fixed.
    for (int i = 0; i < 4; i++) {
        if (raw[i] == leg_contact_[i]) {
            leg_contact_count_[i]++;
        } else {
            leg_contact_[i] = raw[i];
            leg_contact_count_[i] = 1;
        }
        if (leg_contact_count_[i] >= contact_debounce_) {
            leg_contact_stable_[i] = leg_contact_[i];
        }
    }
    contact_msg_count_++;
    last_contact_stamp_ = this->now().seconds();
}

bool GslipPronkNode::leg_in_stance(int leg, const TemplateRow& row) const {
    if (!contact_gated_gains_) {
        return row.in_stance;
    }
    // Fall back to the template if the contact topic goes stale rather than
    // freezing on the last value. A gate that silently keeps asserting a dead
    // signal is the failure mode this project keeps finding.
    const double age = this->now().seconds() - last_contact_stamp_;
    if (last_contact_stamp_ <= 0.0 || age > contact_timeout_s_) {
        if (!contact_stale_warned_) {
            contact_stale_warned_ = true;
            RCLCPP_ERROR(this->get_logger(),
                         "contact gate STALE (age %.2fs) -- falling back to the "
                         "template phase. Gains are no longer contact-gated.",
                         age);
        }
        return row.in_stance;
    }
    contact_stale_warned_ = false;
    return leg_contact_stable_[leg];
}

void GslipPronkNode::trigger_cb(const corgi_msgs::msg::TriggerStamped::SharedPtr msg) {
    trigger_ = msg->enable;
}

void GslipPronkNode::motor_state_cb(const corgi_msgs::msg::MotorStateStamped::SharedPtr msg) {
    motor_state_ = *msg;
}

void GslipPronkNode::imu_cb(const corgi_msgs::msg::ImuStamped::SharedPtr msg) {
    imu_ = *msg;
}

bool GslipPronkNode::load_template(const std::string& path) {
    std::ifstream file(path);
    if (!file.is_open()) return false;

    std::string line;
    if (!std::getline(file, line)) return false;  // header

    template_.clear();
    while (std::getline(file, line)) {
        if (line.empty()) continue;
        std::stringstream ss(line);
        std::string cell;
        TemplateRow row{};
        std::vector<double> values;
        while (std::getline(ss, cell, ',')) {
            values.push_back(std::stod(cell));
        }
        if (values.size() < 5) return false;
        row.t = values[0];
        row.theta = values[1];
        row.beta = values[2];
        row.gamma = values[3];
        row.in_stance = values[4] > 0.5;
        template_.push_back(row);
    }
    // The final row is the wrap-around of the first; dropping it keeps the
    // cycle from stalling for one tick at every stride boundary.
    if (template_.size() > 1) template_.pop_back();

    // --- stance-label duty (window length) ------------------------------
    //
    // The +80 ms label shift fixed the touchdown boundary (regime ratio
    // 0.76 -> 1.30, holds in closed loop) but moved the demand peak to the
    // LIFTOFF boundary: real liftoff happens while the labels still say
    // stance, so the leg starts its fast swing under soft stance gains and
    // pays catch-up when flight gains arrive late. Measured real contact duty
    // is ~0.40 on the on-design legs against the template's ~0.43 window --
    // the window is simply longer than real stance.
    //
    // This resizes the stance window to duty * cycle by moving the LIFTOFF
    // edge only; the onset edge stays where the template (plus any shift)
    // puts it. Applied BEFORE the shift so the two parameters are orthogonal:
    // duty = window length, shift = window placement.
    //
    // Same safety shape as the shift: global, constant, label-only --
    // theta/beta/gamma untouched, no feedback path, cannot chatter.
    if (template_.size() > 1 && stance_label_duty_ > 0.0) {
        const size_t n = template_.size();
        // The labels must form exactly one contiguous circular stance
        // segment for "the liftoff edge" to be well-defined. Refuse
        // anything else rather than guess (see the analyser-gating rule).
        size_t onset = n, transitions = 0;
        for (size_t i = 0; i < n; i++) {
            const bool prev = template_[(i + n - 1) % n].in_stance;
            const bool cur = template_[i].in_stance;
            if (prev != cur) transitions++;
            if (!prev && cur) onset = i;
        }
        const size_t m_target =
            static_cast<size_t>(std::lround(stance_label_duty_ *
                                            static_cast<double>(n)));
        if (transitions != 2 || onset == n) {
            RCLCPP_ERROR(this->get_logger(),
                         "stance_label_duty=%.3f REFUSED: labels have %zu "
                         "transitions (need exactly 2, one stance segment). "
                         "Labels left untouched.",
                         stance_label_duty_, transitions);
        } else if (m_target == 0 || m_target >= n) {
            RCLCPP_ERROR(this->get_logger(),
                         "stance_label_duty=%.3f REFUSED: %zu of %zu rows "
                         "is not a usable window. Labels left untouched.",
                         stance_label_duty_, m_target, n);
        } else {
            size_t m_orig = 0;
            for (size_t i = 0; i < n; i++)
                if (template_[i].in_stance) m_orig++;
            for (size_t i = 0; i < n; i++)
                template_[i].in_stance = false;
            for (size_t i = 0; i < m_target; i++)
                template_[(onset + i) % n].in_stance = true;
            RCLCPP_WARN(this->get_logger(),
                        "STANCE LABEL DUTY set to %.3f (%zu of %zu rows, "
                        "template had %zu). Liftoff edge moved, onset kept; "
                        "runs are NOT comparable to unmodified campaigns.",
                        stance_label_duty_, m_target, n, m_orig);
        }
    }

    // --- stance-label phase shift --------------------------------------
    //
    // Measured (template_contact_lag.py, nine runs, three k_t settings): the
    // schedule's stance window runs ~80 ms AHEAD of actual touchdown, against
    // a ~95 ms commanded stance -- so real stance is spent almost entirely
    // under commanded flight gains (~289 N.m/rad instead of the ~36 virtual
    // spring). Offline replay says delaying the labels ~80 ms takes
    // P(spring | foot down) from 0.6x chance to ~1.6x.
    //
    // The shift rotates ONLY the in_stance labels around the cycle; theta/
    // beta/gamma are untouched, so the trajectory -- and everything reality
    // phase-locks to -- is unchanged. Shifting the whole template would shift
    // reality with it and change nothing.
    //
    // Deliberately GLOBAL and CONSTANT: the per-leg contact gate that
    // re-timed gains from live feedback wrecked the robot (chatter + per-leg
    // positive feedback + internally inconsistent commands). A constant
    // rotation cannot chatter, treats all four legs identically, and keeps
    // the command sequence identical from stride to stride.
    //
    // Positive = labels DELAYED (gains switch later in the cycle). The
    // offline payoff is an open-loop replay estimate; in closed loop the
    // phase equilibrium may partly re-establish -- which is exactly what the
    // experiment measures.
    if (template_.size() > 1 && stance_label_shift_s_ != 0.0) {
        const size_t n = template_.size();
        const double dt = template_.back().t / static_cast<double>(n - 1);
        const long k_raw = std::lround(stance_label_shift_s_ / dt);
        const size_t k = static_cast<size_t>(((k_raw % static_cast<long>(n))
                                              + static_cast<long>(n))
                                             % static_cast<long>(n));
        std::vector<bool> orig(n);
        for (size_t i = 0; i < n; i++) orig[i] = template_[i].in_stance;
        for (size_t i = 0; i < n; i++)
            template_[i].in_stance = orig[(i + n - k) % n];
        RCLCPP_WARN(this->get_logger(),
                    "STANCE LABELS SHIFTED by %+.0f ms (%zu of %zu rows). "
                    "Gain schedule is re-phased against the trajectory; runs "
                    "are NOT comparable to unshifted campaigns.",
                    stance_label_shift_s_ * 1e3, k, n);
    }

    // --- stance beta-sweep scaling (beta-dot slaving, S29's fix) ----------
    //
    // Rolling contact requires beta-dot = v_body / L(theta) at every instant
    // of stance (the foot rim's absolute angle IS beta). The template
    // satisfies this at its own design speed; the robot runs slower, so the
    // clocked beta(t) drags the feet through the ground -- the S28
    // dissipation, and the self-reinforcing "grip costs speed" loop.
    //
    // Because the template is rolling-consistent at v_design, slaving to a
    // slower v is EXACTLY a scaling of the stance sweep about touchdown:
    //   beta'(t) = beta_td + f * (beta(t) - beta_td),  f = v_slave/v_design
    // gives beta-dot' = f * v_design / L = v_slave / L. No kinematics needed.
    //
    // Flight rows get the liftoff offset blended linearly to zero so the
    // next touchdown beta is unchanged and beta is continuous at both
    // boundaries. theta, gamma, labels untouched. Same safety shape as the
    // shift and duty: global, constant, precomputed at load, no feedback
    // path, cannot chatter. 1.0 = shipped behaviour, bit-identical.
    if (template_.size() > 1 && stance_sweep_scale_ != 1.0) {
        const size_t n = template_.size();
        size_t onset = n, transitions = 0;
        for (size_t i = 0; i < n; i++) {
            const bool prev = template_[(i + n - 1) % n].in_stance;
            const bool cur = template_[i].in_stance;
            if (prev != cur) transitions++;
            if (!prev && cur) onset = i;
        }
        size_t m = 0;
        for (size_t i = 0; i < n; i++)
            if (template_[i].in_stance) m++;
        if (stance_sweep_scale_ <= 0.0 || stance_sweep_scale_ > 1.0) {
            RCLCPP_ERROR(this->get_logger(),
                         "stance_sweep_scale=%.3f REFUSED: must be in (0, 1]."
                         " Beta left untouched.", stance_sweep_scale_);
        } else if (transitions != 2 || onset == n || m == 0 || m >= n) {
            RCLCPP_ERROR(this->get_logger(),
                         "stance_sweep_scale=%.3f REFUSED: labels have %zu "
                         "transitions (need exactly 2, one stance segment). "
                         "Beta left untouched.",
                         stance_sweep_scale_, transitions);
        } else {
            const double f = stance_sweep_scale_;
            const double b_td = template_[onset].beta;
            double sweep_orig = 0.0, off = 0.0;
            for (size_t k2 = 0; k2 < m; k2++) {
                const size_t idx = (onset + k2) % n;
                const double b = template_[idx].beta;
                template_[idx].beta = b_td + f * (b - b_td);
                if (k2 == m - 1) {
                    sweep_orig = b - b_td;
                    off = template_[idx].beta - b;  // (f-1)*sweep, negative
                }
            }
            const size_t nf = n - m;
            for (size_t k2 = 0; k2 < nf; k2++) {
                const size_t idx = (onset + m + k2) % n;
                const double s = static_cast<double>(k2 + 1) /
                                 static_cast<double>(nf);
                template_[idx].beta += off * (1.0 - s);
            }
            RCLCPP_WARN(this->get_logger(),
                        "STANCE SWEEP SCALED by %.3f: stance beta sweep "
                        "%.3f -> %.3f rad about touchdown, flight blended "
                        "back over %zu rows. beta-dot is now slaved to "
                        "%.0f%% of the template's design speed; runs are NOT "
                        "comparable to unscaled campaigns.",
                        f, sweep_orig, f * sweep_orig, nf, f * 100.0);
        }
    }
    // --- contact_align (S309, #20): dwell -> roll-matched sweep -> return.
    //
    // Runs AFTER every other beta/label transform and BEFORE the derived
    // geometry below, so onset/liftoff/derived rates see the table as
    // played. Refusals fall back to the untouched table (the duty
    // pattern): this transform must never half-apply.
    if (contact_align_rows_ > 0 && template_.size() > 8) {
        const size_t n = template_.size();
        const size_t D = static_cast<size_t>(contact_align_rows_);
        // Label geometry (pre-derivation, local): one contiguous segment.
        size_t onset = n, transitions = 0, m = 0;
        for (size_t i = 0; i < n; i++) {
            const bool prev = template_[(i + n - 1) % n].in_stance;
            const bool cur = template_[i].in_stance;
            if (prev != cur) transitions++;
            if (!prev && cur) onset = i;
            if (cur) m++;
        }
        const size_t S = contact_sweep_rows_ > 0
                             ? static_cast<size_t>(contact_sweep_rows_) : m;
        const double f = contact_sweep_scale_;
        const size_t R = static_cast<size_t>(std::max(0, contact_ramp_rows_));
        const double dt = template_.back().t / static_cast<double>(n - 1);
        bool ok = true;
        const char* why = "";
        if (transitions != 2 || onset >= n || m == 0 || m >= n) {
            ok = false; why = "labels not one contiguous segment";
        } else if (D + S > n - 8) {
            ok = false; why = "D+S leaves fewer than 8 return rows";
        } else if (!(f > 0.0 && f <= 1.0)) {
            ok = false; why = "contact_sweep_scale outside (0,1]";
        } else if (R >= D) {
            ok = false; why = "contact_ramp_rows >= contact_align_rows";
        } else if (stance_sweep_scale_ != 1.0) {
            ok = false; why = "stance_sweep_scale also set (same idea, "
                              "lower resolution -- pick one)";
        } else if (slave_stance_ || event_sched_) {
            ok = false; why = "slave_stance/event_sched per-leg machinery "
                              "(re-derive geometry before composing)";
        } else if (clock_ff_scale_ != 0.0) {
            ok = false; why = "clock_ff rates derive from the LABEL window, "
                              "which no longer matches the sweep";
        }
        double A = 0.0, ret_rate = 0.0;
        if (ok) {
            const double b0 = template_[onset].beta;
            A = f * (template_[(onset + m - 1) % n].beta - b0);
            const size_t ret_rows = n - D - S;
            ret_rate = std::abs(A) / (static_cast<double>(ret_rows) * dt);
            if (ret_rate > 1.5 * 3.283) {   // S249 pricing guard
                ok = false; why = "return rate exceeds 1.5x template peak";
            } else {
                // The template's own normalised sweep shape g(u), sampled
                // from the ORIGINAL stance rows so the ease profile is
                // preserved rather than a new shape invented.
                std::vector<double> orig(m);
                for (size_t j = 0; j < m; j++)
                    orig[j] = template_[(onset + j) % n].beta;
                const double denom = orig[m - 1] - orig[0];
                auto g = [&](double u) {
                    const double x = u * static_cast<double>(m - 1);
                    const size_t j0 = static_cast<size_t>(x);
                    const size_t j1 = std::min(j0 + 1, m - 1);
                    const double w = x - static_cast<double>(j0);
                    const double b = orig[j0] * (1.0 - w) + orig[j1] * w;
                    return denom != 0.0 ? (b - orig[0]) / denom : 0.0;
                };
                const double per_row = A / static_cast<double>(S);
                for (size_t k = 0; k < n; k++) {
                    const size_t idx = (onset + k) % n;
                    double b;
                    if (k < D) {
                        b = b0;
                        // Optional retraction ramp into the dwell's tail:
                        // approach b0 from below at the sweep's mean rate.
                        if (R > 0 && k >= D - R)
                            b = b0 - static_cast<double>(D - k) * per_row;
                    } else if (k < D + S) {
                        b = b0 + A * g(static_cast<double>(k - D) /
                                       static_cast<double>(S - 1));
                    } else {
                        const double frac =
                            static_cast<double>(k - (D + S) + 1) /
                            static_cast<double>(n - D - S);
                        b = b0 + A * (1.0 - frac);
                    }
                    template_[idx].beta = b;
                }
                // Grep-able engagement + a checksum of the emitted column.
                uint32_t h = 2166136261u;
                for (size_t i = 0; i < n; i++) {
                    const double bv = template_[i].beta;
                    const unsigned char* p =
                        reinterpret_cast<const unsigned char*>(&bv);
                    for (size_t b8 = 0; b8 < sizeof(double); b8++) {
                        h ^= p[b8];
                        h *= 16777619u;
                    }
                }
                RCLCPP_WARN(this->get_logger(),
                            "CONTACT ALIGN set: D=%zu S=%zu f=%.3f R=%zu "
                            "(dwell %.0f ms, sweep %.3f rad at %.3f rad/s, "
                            "return %.3f rad/s) beta-checksum=%08x. Runs "
                            "are NOT comparable to unaligned campaigns.",
                            D, S, f, R,
                            static_cast<double>(D) * dt * 1e3, A,
                            A / (static_cast<double>(S) * dt), ret_rate, h);
            }
        }
        if (!ok) {
            RCLCPP_ERROR(this->get_logger(),
                         "CONTACT ALIGN REFUSED (%s) -- table left "
                         "untouched, running the shipped template.", why);
        }
    }
    // --- Event-scheduler load-time geometry (after ALL label transforms) ---
    //
    // The snap target is the stance-onset row of the labels AS PLAYED, so
    // this must run after duty/shift have had their say. The scheduler
    // needs exactly one contiguous circular stance segment for "the onset"
    // to be well-defined -- same precondition, same refusal shape as duty.
    if (template_.size() > 1) {
        const size_t n = template_.size();
        template_dt_ = template_.back().t / static_cast<double>(n - 1);
        size_t onset = n, transitions = 0, m = 0;
        double max_step = 0.0;
        for (size_t i = 0; i < n; i++) {
            const bool prev = template_[(i + n - 1) % n].in_stance;
            const bool cur = template_[i].in_stance;
            if (prev != cur) transitions++;
            if (!prev && cur) onset = i;
            if (cur) m++;
            max_step = std::max(max_step,
                                std::abs(template_[i].beta -
                                         template_[(i + n - 1) % n].beta));
        }
        sched_labels_ok_ = (transitions == 2 && onset < n && m > 0 && m < n);
        stance_onset_row_ = sched_labels_ok_ ? onset : 0;
        stance_rows_ = m;
        if (sched_labels_ok_) {
            liftoff_row_ = (onset + m) % n;
            stance_sweep_rad_ =
                template_[(onset + m - 1) % n].beta - template_[onset].beta;
            beta_lo_abs_ = template_[(onset + m - 1) % n].beta;

            // The clock rate eq 11 damps to. The stance sweep is linear to
            // 0.296 deg over v070's 18.5 deg (0.529 deg on the v~1.20
            // default), so one constant is a fair reference and avoids
            // differencing rows across the phase edge and the template wrap.
            // Both rates are derived from whichever template was actually
            // loaded -- S164 quoted 6.556 rad/s, which is the DEFAULT
            // template, not the v070 config of record (3.010 rad/s).
            // INTERVALS, not rows: stance_sweep_rad_ spans rows onset..onset+m-1,
            // i.e. (m-1) intervals, and the cyclic remainder is (n-m+1).
            const double stance_dur = static_cast<double>(m - 1) * template_dt_;
            const double flight_dur = static_cast<double>(n - m + 1) * template_dt_;
            clock_rate_stance_ = stance_dur > 0.0
                                     ? stance_sweep_rad_ / stance_dur : 0.0;
            clock_rate_flight_ = flight_dur > 0.0
                                     ? -stance_sweep_rad_ / flight_dur : 0.0;
        }
        tpl_beta_min_ = template_[0].beta;
        tpl_beta_max_ = template_[0].beta;
        for (const auto& r : template_) {
            tpl_beta_min_ = std::min(tpl_beta_min_, r.beta);
            tpl_beta_max_ = std::max(tpl_beta_max_, r.beta);
        }
        // What a HARD snap would have cost: the bound that justifies the
        // blend. Logged, not acted on.
        sched_hard_snap_beta_deg_ =
            (event_snap_limit_s_ / template_dt_) * max_step * 180.0 / M_PI;
        if (event_sched_) {
            if (!sched_labels_ok_) {
                RCLCPP_ERROR(this->get_logger(),
                             "EVENT SCHED REFUSED: labels have %zu "
                             "transitions (need exactly 2, one stance "
                             "segment). Falling back to the global clock.",
                             transitions);
            } else {
                RCLCPP_INFO(this->get_logger(),
                            "Event scheduler geometry: onset row %zu, "
                            "stance %zu of %zu rows, dt %.4f s; a HARD "
                            "%.0f ms snap would step beta_ref by up to "
                            "%.2f deg -- hence the %d-tick blend.",
                            stance_onset_row_, stance_rows_, n,
                            template_dt_, event_snap_limit_s_ * 1e3,
                            sched_hard_snap_beta_deg_, event_blend_ticks_);
            }
        }
    }
    return template_.size() > 1;
}

// Signed shortest distance a - b around the circular template, in rows.
double GslipPronkNode::circ_rows(double a, double b) const {
    const double n = static_cast<double>(template_.size());
    double d = std::fmod(a - b, n);
    if (d < 0.0) d += n;
    if (d >= 0.5 * n) d -= n;
    return d;
}

void GslipPronkNode::sched_event(double t, int leg, size_t master,
                                 const char* ev) {
    if (!sched_csv_.is_open()) return;
    static const char* names = "ABCD";
    sched_csv_ << t << ',' << names[leg] << ',' << leg_index_[leg] << ','
               << master << ','
               << circ_rows(static_cast<double>(leg_index_[leg]) +
                            leg_frac_[leg],
                            static_cast<double>(master)) << ','
               << snap_rows_pending_[leg] << ','
               << (template_[leg_index_[leg]].in_stance ? 1 : 0) << ','
               << (leg_contact_stable_[leg] ? 1 : 0) << ',' << ev << '\n';
}

void GslipPronkNode::sched_reset(size_t master) {
    for (int i = 0; i < 4; i++) {
        leg_index_[i] = master;
        leg_frac_[i] = 0.0;
        snap_rows_pending_[i] = 0.0;
        blend_ticks_left_[i] = 0;
        snaps_this_stride_[i] = 0;
        leg_prev_contact_[i] = leg_contact_stable_[i];
        leg_armed_[i] = false;
        arm_at_stride_[i] = -1;
        stance_run_ticks_[i] = 0;
        overrun_flagged_[i] = false;
    }
    sched_stale_active_ = false;
    sched_tick_count_ = 0;
    for (int i = 0; i < 4; i++) {
        leg_slaved_[i] = false;
        slave_hold_[i] = false;
        slave_wait_[i] = false;
        wait_ticks_[i] = 0;
        slave_ever_[i] = false;
        slave_beta_[i] = 0.0;
        slave_entry_beta_[i] = 0.0;
        slave_ticks_[i] = 0;
        flight_off_[i] = 0.0;
        last_beta_base_[i] = template_[master].beta;
    }
    ekf_fallback_warned_ = false;
    push_rel_quorum_ = 0;
    push_rel_timeout_ = 0;
    push_rel_sole_ = 0;
}

// One scheduler tick, called BEFORE the rows are applied: edge detection
// and snap initiation on this tick's contact state, then clock advance for
// the NEXT tick (mirroring the master's use-then-increment order).
void GslipPronkNode::sched_tick(size_t master, size_t master_stride,
                                double t_now) {
    const double snap_lim_rows = event_snap_limit_s_ / template_dt_;

    // Staleness: degrade to the global clock, never freeze per-leg state.
    const double age = t_now - last_contact_stamp_;
    const bool stale =
        (last_contact_stamp_ <= 0.0 || age > contact_timeout_s_);
    if (stale && !sched_stale_active_) {
        sched_stale_active_ = true;
        RCLCPP_ERROR(this->get_logger(),
                     "EVENT SCHED contact STALE (age %.2fs) -- snapping "
                     "stopped, slewing leg clocks back to the master.",
                     age);
        for (int i = 0; i < 4; i++)
            sched_event(t_now, i, master, "STALE_FALLBACK");
    } else if (!stale && sched_stale_active_) {
        sched_stale_active_ = false;
        RCLCPP_WARN(this->get_logger(),
                    "EVENT SCHED contact fresh again -- resuming snaps.");
    }

    sched_tick_count_++;
    const bool periodic = (sched_tick_count_ % 10 == 0);

    for (int i = 0; i < 4; i++) {
        const bool c = leg_contact_stable_[i];
        const bool rising = c && !leg_prev_contact_[i];
        const bool falling = !c && leg_prev_contact_[i];
        leg_prev_contact_[i] = c;

        if (rising) {
            sched_event(t_now, i, master, "TD");
            if (arm_at_stride_[i] < 0)
                arm_at_stride_[i] = static_cast<long>(master_stride) +
                                    event_arm_strides_;
            if (!leg_armed_[i] && arm_at_stride_[i] >= 0 &&
                static_cast<long>(master_stride) >= arm_at_stride_[i])
                leg_armed_[i] = true;
        }
        if (falling) sched_event(t_now, i, master, "LO");

        // --- Tier 3 slaved stance (replaces snapping entirely) ----------
        if (slave_engaged_) {
            if (!leg_armed_[i] && !leg_slaved_[i]) {
                // Track the master until armed -- same rule as snap mode.
                leg_index_[i] = master;
                leg_frac_[i] = 0.0;
                if (periodic) sched_event(t_now, i, master, "");
                continue;
            }
            // Robot-wide v-source health, evaluated per tick.
            if (slave_v_source_ == "ekf") {
                const double age = t_now - ekf_stamp_;
                if (ekf_stamp_ < 0.0 || age > ekf_timeout_s_ + 0.1) {
                    if (slave_active_) {
                        slave_active_ = false;
                        if (!ekf_fallback_warned_) {
                            ekf_fallback_warned_ = true;
                            RCLCPP_ERROR(this->get_logger(),
                                         "SLAVE STANCE /ekf STALE (age "
                                         "%.2fs) -- falling back to clocked "
                                         "replay.", age);
                        }
                        sched_event(t_now, i, master, "EKF_STALE");
                    }
                } else if (!slave_active_) {
                    slave_active_ = true;
                    ekf_fallback_warned_ = false;
                    RCLCPP_WARN(this->get_logger(),
                                "SLAVE STANCE /ekf fresh -- resuming.");
                }
            }
            if (leg_slaved_[i]) {
                if (!slave_active_) {
                    slave_exit(i, master, t_now, "SLAVE_EXIT_FALLBACK");
                } else if (falling) {
                    slave_exit(i, master, t_now, "SLAVE_EXIT_LIFTOFF");
                } else if (slave_wait_[i]) {
                    // PUSH_WAIT: beta_ref pinned at entry beta under
                    // stance gains, no integration, no clock motion.
                    // Release when the quorum of legs are simultaneously
                    // slaved AND in contact -- every waiting leg on the
                    // SAME tick, which is what makes the push synchronous
                    // -- or alone on this leg's own timeout.
                    wait_ticks_[i]++;
                    int down = 0, down_any = 0;
                    for (int k = 0; k < 4; k++) {
                        if (leg_contact_stable_[k]) down_any++;
                        if (leg_slaved_[k] && leg_contact_stable_[k]) down++;
                    }
                    if (down_any <= 1) {
                        // Sole support: a held foot is a pivot. Roll.
                        slave_wait_[i] = false;
                        push_rel_sole_++;
                        sched_event(t_now, i, master, "PUSH_RELEASE_SOLE");
                    } else if (down >= push_sync_quorum_) {
                        for (int k = 0; k < 4; k++) {
                            if (!slave_wait_[k]) continue;
                            slave_wait_[k] = false;
                            push_rel_quorum_++;
                            sched_event(t_now, k, master,
                                        "PUSH_RELEASE_QUORUM");
                        }
                    } else if (wait_ticks_[i] * template_dt_ >
                               push_sync_max_hold_s_) {
                        slave_wait_[i] = false;
                        push_rel_timeout_++;
                        sched_event(t_now, i, master,
                                    "PUSH_RELEASE_TIMEOUT");
                    }
                } else {
                    slave_ticks_[i]++;
                    if (!slave_hold_[i]) {
                        const double v = slave_v_source_ == "fixed"
                                             ? slave_v_fixed_ : ekf_v_;
                        const double L = lut_L(meas_theta(i));
                        const double dir =
                            stance_sweep_rad_ >= 0.0 ? 1.0 : -1.0;
                        slave_beta_[i] += dir * (v / L) * template_dt_;
                        if ((stance_sweep_rad_ >= 0.0
                                 ? slave_beta_[i] >= beta_lo_abs_
                                 : slave_beta_[i] <= beta_lo_abs_)
                            || std::abs(slave_beta_[i] -
                                        slave_entry_beta_[i]) >=
                                   std::abs(stance_sweep_rad_)) {
                            // ABSOLUTE liftoff angle (handover spec): a
                            // foot landing further along the arc gets a
                            // shorter roll. Sweep done + foot still down
                            // -> HOLD, never the backswing under load.
                            slave_beta_[i] = beta_lo_abs_;
                            slave_hold_[i] = true;
                            sched_event(t_now, i, master, "SLAVE_HOLD");
                        }
                    }
                    if (leg_slaved_[i] && slave_ticks_[i] >
                            static_cast<int>(stance_max_overrun_ratio_ *
                                             static_cast<double>(
                                                 stance_rows_))) {
                        // The timeout may NOT dump a loaded leg into the
                        // flight rows: stiff (12000) flight gains
                        // commanding retract + swing-back against the
                        // ground throw that end of the body up (the rear
                        // "bucking", render 2026-08-20 -- the same
                        // loaded-foot violation as S95/S97, reached
                        // through the one exit path still unguarded, and
                        // push_sync makes legs hold longer so more of
                        // them arrive here still loaded). A stuck stance
                        // degrades to STANDING, which is benign; only a
                        // measured liftoff (or staleness) leaves stance.
                        if (!c) {
                            slave_exit(i, master, t_now,
                                       "SLAVE_EXIT_TIMEOUT");
                        } else if (!slave_hold_[i]) {
                            slave_hold_[i] = true;
                            sched_event(t_now, i, master,
                                        "SLAVE_OVERRUN_HOLD");
                            RCLCPP_WARN(this->get_logger(),
                                        "SLAVE OVERRUN leg %c: stance %d "
                                        "ticks, foot still down -- "
                                        "holding beta (will not enter "
                                        "flight under load).",
                                        "ABCD"[i], slave_ticks_[i]);
                        }
                    }
                }
            } else if (rising && slave_active_) {
                // Scrape/bounce latch: re-entry only after the clock has
                // replayed >= half the flight rows since the last exit.
                const size_t n_rows = template_.size();
                const size_t fl_rows = n_rows - stance_rows_;
                const size_t since =
                    (leg_index_[i] + n_rows - liftoff_row_) % n_rows;
                if (!slave_ever_[i] || since >= fl_rows / 2) {
                    // State-continuous entry: integrate from the beta
                    // this leg was commanded LAST tick -- no jump.
                    leg_slaved_[i] = true;
                    slave_ever_[i] = true;
                    slave_hold_[i] = false;
                    slave_wait_[i] =
                        push_sync_ && static_cast<long>(master_stride) >=
                                          push_sync_arm_strides_;
                    wait_ticks_[i] = 0;
                    slave_beta_[i] = last_beta_base_[i];
                    slave_entry_beta_[i] = last_beta_base_[i];
                    slave_ticks_[i] = 0;
                    flight_off_[i] = 0.0;
                    leg_index_[i] = stance_onset_row_;
                    leg_frac_[i] = 0.0;
                    sched_event(t_now, i, master,
                                slave_wait_[i] ? "PUSH_WAIT"
                                               : "SLAVE_ENTER");
                } else {
                    sched_event(t_now, i, master, "SLAVE_BOUNCE_IGNORED");
                }
            }
            if (periodic) sched_event(t_now, i, master, "");
            continue;  // no snap machinery in slave mode
        }

        if (!leg_armed_[i]) {
            // Track the master until armed -- bit-identical behaviour.
            leg_index_[i] = master;
            leg_frac_[i] = 0.0;
            continue;
        }

        if (stale) {
            // Retarget the blend at the master every tick while stale; the
            // rate clamp below turns this into a bounded slew.
            snap_rows_pending_[i] =
                circ_rows(static_cast<double>(master),
                          static_cast<double>(leg_index_[i]) + leg_frac_[i]);
            if (std::abs(snap_rows_pending_[i]) > 1e-9)
                blend_ticks_left_[i] = std::max(1, event_blend_ticks_);
        } else if (rising && snaps_this_stride_[i] < event_snap_per_stride_) {
            double corr =
                circ_rows(static_cast<double>(stance_onset_row_),
                          static_cast<double>(leg_index_[i]) + leg_frac_[i]);
            // Advance-only: replace a large backward correction (a freeze
            // that would lengthen the stride and regenerate the error)
            // with the complementary forward one. Small backward
            // corrections (<= 10 rows) stay -- a 10 ms freeze is benign
            // and cheaper than a near-full-cycle advance.
            if (event_forward_only_ && corr < -10.0)
                corr += static_cast<double>(template_.size());
            const char* ev = "SNAP_START";
            if (corr > snap_lim_rows) { corr = snap_lim_rows; ev = "SNAP_CLAMPED"; }
            if (corr < -snap_lim_rows) { corr = -snap_lim_rows; ev = "SNAP_CLAMPED"; }
            snap_rows_pending_[i] += corr;
            blend_ticks_left_[i] = std::max(1, event_blend_ticks_);
            snaps_this_stride_[i]++;
            sched_event(t_now, i, master, ev);
        }

        // Overrun diagnostic: row says stance, foot says air, for far
        // longer than the template's stance lasts. WARN only -- liftoff
        // stays free-running by design.
        if (template_[leg_index_[i]].in_stance && !c) {
            stance_run_ticks_[i]++;
            if (!overrun_flagged_[i] &&
                stance_run_ticks_[i] >
                    static_cast<int>(stance_max_overrun_ratio_ *
                                     static_cast<double>(stance_rows_))) {
                overrun_flagged_[i] = true;
                RCLCPP_WARN(this->get_logger(),
                            "SCHED OVERRUN leg %c: row in stance %d ticks "
                            "without contact (template stance %zu rows).",
                            "ABCD"[i], stance_run_ticks_[i], stance_rows_);
                sched_event(t_now, i, master, "OVERRUN");
            }
        } else {
            stance_run_ticks_[i] = 0;
            overrun_flagged_[i] = false;
        }

        if (periodic) sched_event(t_now, i, master, "");
    }
    if (sched_csv_.is_open() && periodic) sched_csv_.flush();
}

// Advance the per-leg clocks for the NEXT tick. Called after the rows are
// applied, mirroring the master's use-then-increment order -- advancing
// inside sched_tick would put every armed leg one row ahead of the master
// it was supposed to be tracking at the arming boundary.
void GslipPronkNode::sched_advance() {
    const size_t n = template_.size();

    // Tier 2 coupling target: the circular mean phase of all four legs
    // (slaved legs contribute their stance progress but are never
    // nudged). Computed once per tick.
    double mean_rows = 0.0;
    bool couple = false;
    if (couple_gain_ != 0.0) {
        double re = 0.0, im = 0.0;
        int cnt = 0;
        for (int i = 0; i < 4; i++) {
            if (!leg_armed_[i]) continue;
            const double a =
                2.0 * M_PI * leg_phase_rows(i) / static_cast<double>(n);
            re += std::cos(a);
            im += std::sin(a);
            cnt++;
        }
        if (cnt == 4 && (re != 0.0 || im != 0.0)) {
            double ang = std::atan2(im, re);
            if (ang < 0.0) ang += 2.0 * M_PI;
            mean_rows = ang * static_cast<double>(n) / (2.0 * M_PI);
            couple = true;
        }
    }

    for (int i = 0; i < 4; i++) {
        if (!leg_armed_[i]) continue;  // tracking the master until armed
        if (leg_slaved_[i]) continue;  // row pinned during slaved stance

        // Nominal 1 row/tick, modulated by the pending correction, total
        // rate clamped to [0, 2.5] rows/tick (backward corrections freeze
        // the clock, never reverse it).
        double step = 0.0;
        if (blend_ticks_left_[i] > 0) {
            step = snap_rows_pending_[i] /
                   static_cast<double>(blend_ticks_left_[i]);
            if (step > 1.5) step = 1.5;
            if (step < -1.0) step = -1.0;
            snap_rows_pending_[i] -= step;
            blend_ticks_left_[i]--;
            if (blend_ticks_left_[i] == 0) {
                if (std::abs(snap_rows_pending_[i]) > 1e-6)
                    blend_ticks_left_[i] = 1;  // rate clamp stretched it
                else
                    snap_rows_pending_[i] = 0.0;
            }
        }
        // Tier 2 nudge: flight rows only, never fights the ground.
        if (couple && !template_[leg_index_[i]].in_stance) {
            double nudge = couple_gain_ *
                           circ_rows(mean_rows,
                                     static_cast<double>(leg_index_[i]) +
                                         leg_frac_[i]);
            if (nudge > couple_clamp_) nudge = couple_clamp_;
            if (nudge < -couple_clamp_) nudge = -couple_clamp_;
            step += nudge;
        }

        leg_frac_[i] += 1.0 + step;
        while (leg_frac_[i] >= 1.0) {
            leg_frac_[i] -= 1.0;
            leg_index_[i]++;
            if (leg_index_[i] >= n) {
                leg_index_[i] = 0;
                snaps_this_stride_[i] = 0;  // per-stride snap latch
            }
        }
    }
}

void GslipPronkNode::update_attitude(double& roll, double& pitch, double& yaw) const {
    const double x = imu_.orientation.x, y = imu_.orientation.y;
    const double z = imu_.orientation.z, w = imu_.orientation.w;
    roll = std::atan2(2.0 * (w * x + y * z), 1.0 - 2.0 * (x * x + y * y));
    pitch = std::asin(std::max(-1.0, std::min(1.0, 2.0 * (w * y - z * x))));
    yaw = std::atan2(2.0 * (w * z + x * y), 1.0 - 2.0 * (y * y + z * z));
}

double GslipPronkNode::lateral_force(int leg_index, bool in_stance) const {
    // yaw_ref_set_ is the "template is running" flag, same gate as
    // gamma_correction: keeps the settle phase clean.
    if (f_lateral_ == 0.0 || !in_stance || !yaw_ref_set_) return 0.0;

    // Module order is A=FL, B=FR, C=RR, D=RL, so the forelimbs are 0 and 1.
    if (f_lateral_front_only_ && leg_index > 1) return 0.0;

    // Body +y -> leg-frame outward. Left legs abduct toward +y, right legs
    // toward -y.
    static const double lat_sign[4] = {+1.0, -1.0, -1.0, +1.0};

    // Negated: J^T wants the force the foot puts INTO the ground.
    return -f_lateral_ * lat_sign[leg_index];
}

// Apply runtime changes to the impedance gains. Everything else is ignored,
// NOT rejected -- see the comment in the else branch.
rcl_interfaces::msg::SetParametersResult GslipPronkNode::on_set_params(
    const std::vector<rclcpp::Parameter>& params) {
    rcl_interfaces::msg::SetParametersResult res;
    res.successful = true;
    for (const auto& p : params) {
        const std::string& n = p.get_name();
        if (n == "k_radial") k_radial_ = p.as_double();
        else if (n == "k_lateral") k_lateral_ = p.as_double();
        else if (n == "k_tangential") k_tangential_ = p.as_double();
        else if (n == "b_radial") b_radial_ = p.as_double();
        else if (n == "b_lateral") b_lateral_ = p.as_double();
        else if (n == "b_tangential") b_tangential_ = p.as_double();
        else if (n == "k_flight") k_flight_ = p.as_double();
        else if (n == "b_flight") b_flight_ = p.as_double();
        else if (n == "clock_ff_scale") clock_ff_scale_ = p.as_double();
        else if (n == "clock_ff_phase") clock_ff_phase_ = p.as_string();
        else {
            // IGNORE, do not reject. This callback fires for EVERY parameter
            // set, including the launch file's initial declaration of all 60+
            // of them -- rejecting one aborts the node at startup with
            // InvalidParameterValueException (measured: exit -6 on
            // `contact_gated_gains`, log S146). Typo protection is not this
            // callback's job; `ros2 param set` on an undeclared name already
            // fails at the service layer.
            continue;
        }
        RCLCPP_WARN(this->get_logger(), "LIVE GAIN SET: %s = %.4f",
                    n.c_str(), p.as_double());
    }
    return res;
}

// Once per stride, at apex, recompute the beta correction and hold it.
//
// Apex is vz crossing + -> - with no foot down. Requiring airborne matters:
// the body's vertical velocity also changes sign during stance (at peak
// compression), and correcting there would fire mid-stance on a loaded foot --
// which the shipped scheduler forbids for good reason (S102).
void GslipPronkNode::update_apex_feedback() {
    if (apex_fb_gain_ == 0.0 && apex_dc_gain_ == 0.0) {
        apex_beta_offset_ = 0.0;   // stays bit-identical when off
        apex_dc_offset_ = 0.0;
        return;
    }
    // Each row zeroes its own offset when individually off, so enabling one
    // channel never resurrects a held value from the other.
    if (apex_fb_gain_ == 0.0) apex_beta_offset_ = 0.0;
    if (apex_dc_gain_ == 0.0) apex_dc_offset_ = 0.0;

    // Latch-up guard (S268 S3): when apexes stop, bleed the held offsets to
    // zero. BEFORE the stale-data return below, deliberately -- a channel
    // that has gone blind AND stopped apexing is exactly the case that
    // latched. Linear ramp at (row clamp)/decay_s per second, so it is
    // gentle (no step transients, the stale branch's stated intent) and
    // terminates at exactly 0.0.
    const double now_s = this->now().seconds();
    if (apex_hold_decay_s_ > 0.0 && apex_last_fire_s_ >= 0.0 &&
        (apex_beta_offset_ != 0.0 || apex_dc_offset_ != 0.0) &&
        (now_s - apex_last_fire_s_) > apex_hold_grace_s_) {
        double dt = apex_decay_prev_s_ >= 0.0 ? now_s - apex_decay_prev_s_
                                              : 0.0;
        if (dt < 0.0) dt = 0.0;
        if (dt > 0.05) dt = 0.05;   // clock-jump guard
        if (!apex_decay_warned_) {
            apex_decay_warned_ = true;
            RCLCPP_WARN(this->get_logger(),
                        "APEX HOLD DECAY: no apex for %.2f s (grace %.2f), "
                        "bleeding held offsets to zero over %.2f s "
                        "(beta %+.3f deg, d_lam %+.3f deg)",
                        now_s - apex_last_fire_s_, apex_hold_grace_s_,
                        apex_hold_decay_s_,
                        apex_beta_offset_ * 180.0 / M_PI,
                        apex_dc_offset_ * 180.0 / M_PI);
        }
        const double sb = apex_beta_limit_ / apex_hold_decay_s_ * dt;
        const double sd = apex_dc_limit_ / apex_hold_decay_s_ * dt;
        apex_beta_offset_ -= std::copysign(
            std::min(sb, std::fabs(apex_beta_offset_)), apex_beta_offset_);
        apex_dc_offset_ -= std::copysign(
            std::min(sd, std::fabs(apex_dc_offset_)), apex_dc_offset_);
    }
    apex_decay_prev_s_ = now_s;
    const bool airborne = !(leg_contact_stable_[0] || leg_contact_stable_[1] ||
                            leg_contact_stable_[2] || leg_contact_stable_[3]);
    const bool stale =
        ekf_stamp_ < 0.0 ||
        (this->now().seconds() - ekf_stamp_) > ekf_timeout_s_;
    if (stale) {
        // A channel that is enabled and has NEVER had data is not "stale", it
        // is not running. Say so, at most once, at ERROR: silence here cost
        // ten runs that certified a channel doing nothing.
        if (ekf_stamp_ < 0.0 && !apex_starved_warned_) {
            apex_starved_warned_ = true;
            RCLCPP_ERROR(this->get_logger(),
                         "APEX BETA FB STARVED: gain=%.3f dc_gain=%.3f but no "
                         "message has EVER arrived on '%s'. The channel is "
                         "INERT and this run is NOT a test of it.",
                         apex_fb_gain_, apex_dc_gain_,
                         apex_odom_topic_.c_str());
        }
        // Hold the last correction rather than reverting to zero: a step to
        // zero mid-flight is a beta transient, and the whole point of holding
        // per stride is that beta does not move within one.
        apex_vz_prev_guard();
        return;
    }
    if (airborne) apex_airborne_ticks_++; else apex_airborne_ticks_ = 0;
    const bool crossing = ekf_vz_prev_ > 0.0 && ekf_vz_ <= 0.0;
    // S296 verification step 1: per-crossing diagnostic, env-gated and
    // default-off (expect ~90 crossings / 24 s, ~45 with legs_down=0).
    static const bool xdebug = std::getenv("CORGI_APEX_XDEBUG") != nullptr;
    if (xdebug && crossing) {
        const int down = (leg_contact_stable_[0] ? 1 : 0) +
                         (leg_contact_stable_[1] ? 1 : 0) +
                         (leg_contact_stable_[2] ? 1 : 0) +
                         (leg_contact_stable_[3] ? 1 : 0);
        RCLCPP_WARN(this->get_logger(),
                    "APEX XDEBUG: crossing t=%.3f legs_down=%d armed=%d "
                    "airborne_ticks=%d", now_s, down, apex_armed_ ? 1 : 0,
                    apex_airborne_ticks_);
    }
    if (airborne && apex_armed_ && crossing) {
        apex_fire(now_s, ekf_vx_, ekf_z_, ekf_vy_, roll_,
                  imu_.angular_velocity.x);
    } else if (!airborne && apex_armed_ && crossing) {
        // S296 latch-and-defer: the apex passed with a foot still down
        // (about half of them on the healthy pronk, S296). Correcting a
        // loaded foot stays forbidden (S102) -- latch the crossing with
        // the K-row inputs sampled NOW (vy is ballistic-constant and
        // rho/drho barely move in flight) and apply at the first stable-
        // airborne tick. A newer crossing overwrites an unconsumed
        // latch: the freshest apex is the one worth correcting from.
        apex_pending_ = true;
        apex_pending_s_ = now_s;
        apex_pending_vx_ = ekf_vx_;
        apex_pending_z_ = ekf_z_;
        apex_pending_vy_ = ekf_vy_;
        apex_pending_roll_ = roll_;
        apex_pending_wx_ = imu_.angular_velocity.x;
    }
    if (apex_pending_) {
        if (now_s - apex_pending_s_ > 0.30) {
            apex_pending_ = false;   // flight never came; drop the latch
        } else if (airborne && apex_armed_ && apex_airborne_ticks_ >= 20) {
            // >= 20 ms of continuous airborne (two contact samples of
            // age): a mid-flight contact blip that survives the 3-sample
            // debounce cannot host this apply.
            apex_fire(now_s, apex_pending_vx_, apex_pending_z_,
                      apex_pending_vy_, apex_pending_roll_,
                      apex_pending_wx_);
        }
    }
    if (!airborne) apex_armed_ = true;   // re-arm on the next stance
    ekf_vz_prev_ = ekf_vz_;
}

// One apex: apply both enabled rows from the given inputs (immediate
// path passes the live state; the S296 deferred path passes the state
// sampled at the crossing), throttled print, disarm, and clear any
// pending latch so a stale one cannot fire later in the same flight.
void GslipPronkNode::apex_fire(double now_s, double vx, double z,
                               double vy, double roll_v, double wx) {
    apex_count_++;
    apex_last_fire_s_ = now_s;    // resets the S268 latch-up guard
    apex_decay_warned_ = false;
    if (apex_fb_gain_ != 0.0) {
        const double d = apex_fb_gain_ *
                         (apex_k_vx_ * (vx - apex_vx_star_) +
                          apex_k_h_ * (z - apex_h_star_));
        apex_beta_offset_ =
            std::max(-apex_beta_limit_, std::min(apex_beta_limit_, d));
        if (apex_count_ == 1 || apex_count_ % 20 == 0) {
            RCLCPP_WARN(this->get_logger(),
                        "APEX BETA FB FIRED: n=%ld d_beta=%+.3f deg "
                        "(vx %.4f vs %.4f, h %.4f vs %.4f)",
                        apex_count_, apex_beta_offset_ * 180.0 / M_PI,
                        vx, apex_vx_star_, z, apex_h_star_);
        }
    }
    if (apex_dc_gain_ != 0.0) {
        // Stars are all 0 at the S263 orbit (see the header block), so
        // the error IS the state. wx is the IMU roll rate, the same
        // signal gamma_correction damps.
        const double d = apex_dc_gain_ *
                         (apex_dc_k_vy_ * vy +
                          apex_dc_k_rho_ * roll_v +
                          apex_dc_k_drho_ * wx);
        apex_dc_offset_ =
            std::max(-apex_dc_limit_, std::min(apex_dc_limit_, d));
        if (apex_count_ == 1 || apex_count_ % 20 == 0) {
            RCLCPP_WARN(this->get_logger(),
                        "APEX DIFF CAMBER FIRED: n=%ld d_lam=%+.3f deg "
                        "(vy %+.4f rho %+.3f deg drho %+.3f rad/s)",
                        apex_count_, apex_dc_offset_ * 180.0 / M_PI,
                        vy, roll_v * 180.0 / M_PI, wx);
        }
    }
    apex_armed_ = false;       // one correction per flight phase
    apex_pending_ = false;
}

// Split out so the stale path cannot forget it and silently latch a stale
// edge into the next flight phase.
void GslipPronkNode::apex_vz_prev_guard() { ekf_vz_prev_ = ekf_vz_; }

double GslipPronkNode::gamma_correction(int leg_index) const {
    if (!yaw_ref_set_) return 0.0;

    // Module order is A=FL, B=FR, C=RR, D=RL.
    static const double roll_sign[4] = {+1.0, -1.0, -1.0, +1.0};  // left vs right
    static const double yaw_sign[4] = {+1.0, +1.0, -1.0, -1.0};   // front vs rear

    double yaw_err = yaw_ - yaw_ref_;
    while (yaw_err > M_PI) yaw_err -= 2.0 * M_PI;
    while (yaw_err < -M_PI) yaw_err += 2.0 * M_PI;

    const double wx = imu_.angular_velocity.x;  // roll rate
    const double wz = imu_.angular_velocity.z;  // yaw rate

    double yaw_part = yaw_sign[leg_index] * (k_yaw_ * yaw_err + d_yaw_ * wz);
    if (gamma_yaw_limit_ > 0.0) {
        // Gentle hold (log s89, C2): the yaw term alone is clamped small
        // enough that it cannot saturate into a commanded lean. 0 = off,
        // identical code path to before the parameter existed.
        yaw_part = std::max(-gamma_yaw_limit_,
                            std::min(gamma_yaw_limit_, yaw_part));
    }
    const double correction =
        roll_sign[leg_index] * (k_roll_ * roll_ + d_roll_ * wx) + yaw_part;

    return std::max(-gamma_limit_, std::min(gamma_limit_, correction));
}

double GslipPronkNode::pitch_correction(int leg_index, bool in_stance) const {
    // Off is EXACTLY off, so every pre-2026-08-20 run is reproducible.
    if (k_pitch_ == 0.0 && d_pitch_ == 0.0) return 0.0;
    // Stance only (a leg needs ground to pitch the body) and only once
    // the stride loop is running, the same two gates lateral_force uses.
    if (!in_stance || !yaw_ref_set_) return 0.0;

    // A,B front; C,D rear -- the partition yaw_sign already uses, applied
    // to leg length instead of camber.
    static const double pitch_sign[4] = {+1.0, +1.0, -1.0, -1.0};

    const double wy = imu_.angular_velocity.y;   // pitch rate
    const double u = k_pitch_ * pitch_ + d_pitch_ * wy;
    const double clamped = std::max(-pitch_limit_, std::min(pitch_limit_, u));
    return pitch_sign[leg_index] * clamped;
}

// One 1 ms tick of the per-leg touchdown clocks behind the stance-peak dip.
// A touchdown ARMS a leg only if it follows >= dip_rearm_ms of stable flight;
// leaving contact disarms it. Uses leg_contact_stable_ (the 3-sample
// debounce contact_cb already applies), never the raw flag.
void GslipPronkNode::dip_tick() {
    for (int i = 0; i < 4; i++) {
        const bool st = leg_contact_stable_[i];
        if (st) {
            if (!dip_prev_stable_[i]) {
                dip_since_td_ticks_[i] =
                    (dip_flight_ticks_[i] >= gamma_acker_dip_rearm_ms_) ? 0 : -1;
            } else if (dip_since_td_ticks_[i] >= 0) {
                dip_since_td_ticks_[i]++;
            }
            dip_flight_ticks_[i] = 0;
        } else {
            dip_since_td_ticks_[i] = -1;
            dip_flight_ticks_[i]++;
        }
        dip_prev_stable_[i] = st;
    }
}

double GslipPronkNode::apex_diffcamber(int leg_index) const {
    // Identically zero unless the apex channel is on -- update_apex_feedback
    // zeroes the offset whenever apex_dc_gain_ is 0.0, the S135 bit-identity
    // posture. Partition: model lam_l applies to the LEFT pair (A=FL, D=RL),
    // lam_r = -lam_l to the RIGHT pair (B=FR, C=RR) -- the same left/right
    // array as gamma_correction's roll_sign. No settle gate needed: the
    // offset can only become nonzero at a detected apex, which requires
    // airborne, which the settle never is.
    static const double lr_sign[4] = {+1.0, -1.0, -1.0, +1.0};
    return lr_sign[leg_index] * apex_dc_offset_;
}

double GslipPronkNode::gamma_openloop(int leg_index) const {
    // Off is EXACTLY off: dir 0 and ff 0 add literal 0.0 in apply_row,
    // keeping every pre-existing run bit-identical.
    const bool closed_loop = gamma_acker_ff_ > 0.0;
    if (!closed_loop && gamma_acker_dir_ == 0.0) return 0.0;

    // Gated like gamma_correction and steer_command, and for steer_command's
    // documented reasons: a held offset during the settle twists the legs
    // against the ground and fires check_ramp's template-time fiducial early.
    if (!yaw_ref_set_) return 0.0;

    // Same left/right partition as roll_sign/steer_sign. gamma > 0 abducts
    // outward, so s * lr_sign < 0 marks the pair whose contacts move TOWARD
    // the turn centre -- the inner pair, which takes lam_in (it runs the
    // tighter circle; camber_roll.py --acker is the sign-convention source).
    static const double lr_sign[4] = {+1.0, -1.0, -1.0, +1.0};
    double s, lam_in, lam_out;
    if (closed_loop) {
        // S232/S235: heading error against the SAME reference the
        // differential arm tracks (advance_yaw_ref); turn_err_limit_ clips
        // that reference, so a stalled robot cannot wind this loop up
        // (S223's failure mode).
        double yaw_err = yaw_ - yaw_ref_;
        while (yaw_err > M_PI) yaw_err -= 2.0 * M_PI;
        while (yaw_err < -M_PI) yaw_err += 2.0 * M_PI;
        const double wz = imu_.angular_velocity.z;
        // dir +1 (lean right) drives yaw NEGATIVE (S88 sign convention), so
        // the feedforward for a commanded turn is -sign(turn_rate)*ff, and a
        // positive yaw error (heading left of the reference) needs MORE
        // positive lambda: k_acker_yaw > 0 is the stabilising sign.
        const double s_tr = turn_rate_ < 0.0 ? -1.0 : 1.0;
        const double lam_cmd = -s_tr * gamma_acker_ff_
                               + k_acker_yaw_ * yaw_err + d_acker_yaw_ * wz;
        s = lam_cmd > 0.0 ? 1.0 : -1.0;
        // Magnitude confined to the measured proportional region [min, hi]
        // (R ~3.0 m at 5 deg to 2.3 m at 15 deg, S235); in = out, as the
        // whole R(lambda) map was measured.
        lam_in = lam_out = std::min(gamma_acker_hi_,
                                    std::max(gamma_acker_min_,
                                             std::fabs(lam_cmd)));
    } else {
        s = gamma_acker_dir_ > 0.0 ? 1.0 : -1.0;
        lam_in = gamma_acker_in_;
        lam_out = gamma_acker_out_;
    }
    const double signed_unit = s * lr_sign[leg_index];
    const double mag = signed_unit < 0.0 ? lam_in : lam_out;

    const double ramp =
        gamma_acker_ramp_ticks_ > 0
            ? std::min(1.0, static_cast<double>(acker_ramp_count_) /
                                gamma_acker_ramp_ticks_)
            : 1.0;

    double u = signed_unit * mag * ramp;

    // Stance-peak dip: raised-cosine relief inside [t0, t1] ms after an armed
    // touchdown. Scales the TERM, so it is still clamped below and still
    // exactly zero when dir is 0. Identically off at dip 0.0.
    if (gamma_acker_dip_ > 0.0) {
        const int tau = dip_since_td_ticks_[leg_index];
        const int t0 = gamma_acker_dip_t0_ms_, t1 = gamma_acker_dip_t1_ms_;
        if (tau >= t0 && tau <= t1 && t1 > t0) {
            const double x = static_cast<double>(tau - t0) / (t1 - t0);
            const double w = 0.5 * (1.0 - std::cos(2.0 * M_PI * x));
            u *= (1.0 - gamma_acker_dip_ * w);
        }
    }
    return std::max(-gamma_acker_limit_, std::min(gamma_acker_limit_, u));
}

// -> the per-side beta differential to command, in radians, already clamped.
//
// One scalar for the whole robot; apply_row multiplies it by the leg's
// left/right sign. Open-loop bias plus heading feedback, so a fixed
// steer_offset can be swept on its own (k_steer_yaw = 0) to measure the
// channel's authority before any loop is closed.
//
// yaw_ is trustworthy: it matches Supervisor ground truth to 1.17 deg over a
// whole pass, so the historic failure to hold heading was authority, not
// estimation. Guarded on yaw_ref_set_ exactly like gamma_correction -- before
// the reference is latched (i.e. during standup and the settle) there is no
// error to act on, and only the open-loop term applies.
//
// The gain SIGN is not obvious from the geometry: which way a rolling
// differential turns the body depends on the sense of beta and of the
// world-frame yaw together. Decide it from the open-loop runs and negate the
// gain if the correction makes things worse -- the same reason k_roll/k_yaw
// are parameters.
double GslipPronkNode::steer_command() const {
    // NOTHING is steered until the stride loop starts. yaw_ref_set_ is the
    // flag for that: false through standup, through the hold-for-trigger loop
    // and through the settle, true from the first template row onward.
    //
    // This gates the OPEN-LOOP offset as well as the feedback, which matters
    // for two separate reasons:
    //
    //   Physically, execute_running_phase holds the settle pose with
    //   in_stance = true, so a stance-gated offset would twist the legs against
    //   the ground for 2.5 s while the robot is settling onto them after the
    //   support box is removed -- corrupting the very touchdown the settle
    //   exists to protect.
    //
    //   For measurement, check_ramp.py recovers template time from the first
    //   non-zero COMMANDED beta. Steering during the settle fires that fiducial
    //   about 4.6 s early and silently relabels the standing settle as the hop
    //   segment. That is exactly what the first two open-loop runs did: 0.0%
    //   flight, 100% all-down, theta pinned at 97 deg -- a picture of a robot
    //   standing still, reported as a failed hop.
    if (!yaw_ref_set_) return 0.0;

    double yaw_err = yaw_ - yaw_ref_;
    while (yaw_err > M_PI) yaw_err -= 2.0 * M_PI;
    while (yaw_err < -M_PI) yaw_err += 2.0 * M_PI;

    const double wz = imu_.angular_velocity.z;  // yaw rate
    const double u = steer_offset_ + k_steer_yaw_ * yaw_err + d_steer_yaw_ * wz;

    return std::max(-steer_limit_, std::min(steer_limit_, u));
}

// Advance the commanded heading by one control tick.
//
// Called only from the stride loop, i.e. only after yaw_ref_ is latched, so
// with turn_rate_ = 0 the reference never moves and this is a no-op.
//
// Two guards, and they are guarding different things:
//
//   The WRAP keeps yaw_ref_ in the same +-pi representation as yaw_. It is not
//   what saves the control law -- steer_command() wraps the error with `while`
//   loops, so it already handles a reference that has been integrating for
//   minutes. It matters for the log line and for keeping a long run's reference
//   from drifting off into a range where the difference loses precision.
//
//   The CLAMP is the one that earns its place. The wrapped error is what the
//   loop acts on, so if the commanded rate exceeds what the channel can deliver
//   the reference walks away from the robot, the error grows past pi, wraps,
//   and the correction SIGN FLIPS -- the robot suddenly steers hard the wrong
//   way while the command looks perfectly reasonable. That is precisely the
//   regime an envelope sweep is built to visit, so it cannot be left to chance.
//   Holding the reference back at turn_err_limit_ makes an over-command
//   degrade into "turning as fast as it can" instead of into garbage, and the
//   measured-vs-commanded yaw rate in check_turn.py still reports the shortfall.
void GslipPronkNode::advance_yaw_ref(double dt) {
    if (turn_rate_ == 0.0) return;

    yaw_ref_ += turn_rate_ * dt;
    while (yaw_ref_ > M_PI) yaw_ref_ -= 2.0 * M_PI;
    while (yaw_ref_ < -M_PI) yaw_ref_ += 2.0 * M_PI;

    if (turn_err_limit_ > 0.0) {
        double err = yaw_ref_ - yaw_;
        while (err > M_PI) err -= 2.0 * M_PI;
        while (err < -M_PI) err += 2.0 * M_PI;
        if (err > turn_err_limit_) yaw_ref_ -= err - turn_err_limit_;
        else if (err < -turn_err_limit_) yaw_ref_ -= err + turn_err_limit_;
        while (yaw_ref_ > M_PI) yaw_ref_ -= 2.0 * M_PI;
        while (yaw_ref_ < -M_PI) yaw_ref_ += 2.0 * M_PI;
    }
}

double GslipPronkNode::leg_phase_rows(int i) const {
    if (leg_slaved_[i]) {
        const double prog =
            std::min(1.0, std::abs(slave_beta_[i] - slave_entry_beta_[i]) /
                              std::max(1e-6, std::abs(stance_sweep_rad_)));
        return static_cast<double>(stance_onset_row_) +
               prog * static_cast<double>(stance_rows_);
    }
    return static_cast<double>(leg_index_[i]) + leg_frac_[i];
}

void GslipPronkNode::ekf_cb(const nav_msgs::msg::Odometry::SharedPtr msg) {
    // Body-frame forward speed; corgi_leg_odom publishes twist in
    // base_link, so linear.x is the rolling-relevant component.
    ekf_v_ = msg->twist.twist.linear.x;
    // The apex channel needs vertical velocity (to find apex) and height (a
    // state it feeds back). Captured unconditionally: they are two field
    // reads, and gating them on apex_fb_gain_ would mean the first stride
    // after enabling the channel ran on stale values.
    ekf_vx_ = msg->twist.twist.linear.x;
    ekf_vy_ = msg->twist.twist.linear.y;   // apex diff-camber row (y = left)
    ekf_vz_ = msg->twist.twist.linear.z;
    ekf_z_ = msg->pose.pose.position.z;
    ekf_stamp_ = this->now().seconds();
}

bool GslipPronkNode::load_ltheta_lut(const std::string& path) {
    std::ifstream f(path);
    if (!f.is_open()) return false;
    std::string line;
    if (!std::getline(f, line)) return false;  // header
    lut_theta_.clear();
    lut_L_.clear();
    while (std::getline(f, line)) {
        if (line.empty()) continue;
        const auto comma = line.find(',');
        if (comma == std::string::npos) return false;
        const double th = std::stod(line.substr(0, comma)) * M_PI / 180.0;
        const double L = std::stod(line.substr(comma + 1));
        if (!lut_theta_.empty() && th <= lut_theta_.back()) return false;
        if (L <= 0.05 || L > 1.0) return false;
        lut_theta_.push_back(th);
        lut_L_.push_back(L);
    }
    return lut_theta_.size() >= 50;
}

double GslipPronkNode::lut_L(double theta) const {
    if (theta <= lut_theta_.front()) return lut_L_.front();
    if (theta >= lut_theta_.back()) return lut_L_.back();
    const auto it = std::lower_bound(lut_theta_.begin(), lut_theta_.end(),
                                     theta);
    const size_t j = static_cast<size_t>(it - lut_theta_.begin());
    const double f = (theta - lut_theta_[j - 1]) /
                     (lut_theta_[j] - lut_theta_[j - 1]);
    return lut_L_[j - 1] + f * (lut_L_[j] - lut_L_[j - 1]);
}

double GslipPronkNode::meas_theta(int leg) const {
    switch (leg) {
        case 0: return motor_state_.module_a.theta;
        case 1: return motor_state_.module_b.theta;
        case 2: return motor_state_.module_c.theta;
        default: return motor_state_.module_d.theta;
    }
}

// Measured ABAD angle, same source as the theta accessor above. Used by the
// stance-peak yield, which blends the command toward this inside its window.
double GslipPronkNode::measured_gamma(int leg_index) const {
    switch (leg_index) {
        case 0: return motor_state_.module_a.gamma;
        case 1: return motor_state_.module_b.gamma;
        case 2: return motor_state_.module_c.gamma;
        default: return motor_state_.module_d.gamma;
    }
}

void GslipPronkNode::slave_exit(int leg, size_t master, double t_now,
                                const char* why) {
    leg_slaved_[leg] = false;
    slave_hold_[leg] = false;
    slave_wait_[leg] = false;
    leg_index_[leg] = liftoff_row_;
    leg_frac_[leg] = 0.0;
    // Residual offset blends to zero across the flight rows so the next
    // touchdown meets the template's beta (the stance_sweep_scale
    // precedent: continuity at both boundaries).
    flight_off_[leg] = slave_beta_[leg] - template_[liftoff_row_].beta;
    sched_event(t_now, leg, master, why);
}

// All four legs on one row: standup, settle, hold, and the global-clock
// stride loop. Byte-for-byte the historical behaviour -- apply_rows with
// four identical rows performs the same per-leg computations in the same
// order as the old single-row body did.
void GslipPronkNode::apply_row(const TemplateRow& row) {
    apply_rows({&row, &row, &row, &row});
}

// Per-leg rows: the event scheduler's path. Leg i's reference AND gain
// regime both come from rows[i] -- the one-phase-description-per-leg
// consistency the 2026-08-17 failure demands (see the post-mortem above).
// steer_command() stays once per tick: one yaw error per robot.
void GslipPronkNode::apply_rows(const std::array<const TemplateRow*, 4>& rows) {
    update_attitude(roll_, pitch_, yaw_);

    // One tick of the open-loop camber entry ramp. Counted here, gated on
    // yaw_ref_set_, so the settle contributes nothing and the ramp starts
    // with the first stride tick.
    if (yaw_ref_set_ && acker_ramp_count_ < gamma_acker_ramp_ticks_)
        acker_ramp_count_++;
    // Off is exactly off: no state is touched unless the dip is enabled, so
    // the hot path of every existing campaign is unchanged.
    if ((gamma_acker_dip_ > 0.0 || gamma_acker_yield_ > 0.0) && yaw_ref_set_) dip_tick();

    // The radial reference is the spring's REST length, not the template's
    // compressed trajectory.
    //
    // In SLIP-RF the rest length l0 is constant and l(t) is what the dynamics
    // produce under load -- an output, not a setpoint. Feeding l(t) to an
    // impedance controller as its rest position makes the leg compress by
    // F/k on top of a trajectory that already contains the compression,
    // double-counting it. Measured: commanded theta bottomed at 84.4 deg
    // while the leg reached 71-75 deg, 10-13 deg deeper on every damping
    // setting tried.
    //
    // Holding theta at the rest value instead reproduces the model: the leg
    // compresses to 84.4 deg under load, which at 8941 N/m is 262 N per leg,
    // 1048 N total, 3.56 body weights -- against the 3.64 the fixed point
    // predicts.
    //
    // beta still follows the template: that is the clocked-torque part, the
    // leg angle the controller genuinely has to drive.
    //
    // (theta_ref moved into the per-leg loop. With spring_rest_reference_
    // ON it is CONSTANT and per-leg rows change nothing here; OFF -- which
    // is the config of record, S117: on kills the hop, air 0.0% -- each leg
    // tracks its own row's theta.)

    // Left/right selector, same partition as gamma_correction's roll_sign.
    // A=FL, B=FR, C=RR, D=RL.
    static const double steer_sign[4] = {+1.0, -1.0, -1.0, +1.0};

    // One steering command for the whole robot, evaluated once per tick rather
    // than per leg so all four legs act on the same yaw error.
    const double u = steer_command();

    // Where the differential is applied within the stride. Stance is the only
    // place it can do anything: the foot rolls when it is DOWN, so a sweep in
    // flight contributes nothing (the same reason peak-to-peak beta overstates
    // the rolling sweep -- the swing-back rolls nothing).
    //
    // steer_prepose additionally drives the leg the OTHER way during flight, so
    // it touches down pre-positioned at -s*u and sweeps through to +s*u. That
    // doubles the swept differential for free, at the cost of a bigger step at
    // the stance/flight boundaries. Off by default: try it only if the plain
    // gate turns out to be short on authority.
    //
    // (The stance gate is now per leg -- rows[i].in_stance -- so a steered
    // leg sweeps when ITS row is in stance, consistent with its gains.)

    for (size_t i = 0; i < imp_cmd_modules_.size(); i++) {
        const TemplateRow& row = *rows[i];
        auto* cmd = imp_cmd_modules_[i];
        const double s = steer_sign[i];
        const double gate =
            row.in_stance ? 1.0 : (steer_prepose_ ? -1.0 : 0.0);
        // Differential leg length for body pitch; identically 0.0 unless
        // the channel is on (log S115).
        cmd->theta = (spring_rest_reference_ ? theta_rest_ : row.theta)
                     + pitch_correction(static_cast<int>(i), row.in_stance);
        // beta base: slaved stance integrates its own reference; after a
        // slave exit the residual offset blends to zero across the
        // flight rows. Both are identically inert unless the Tier 3
        // machinery set them (flight_off_ stays 0.0 otherwise).
        double beta_base = row.beta;
        if (leg_slaved_[i]) {
            beta_base = slave_beta_[i];
        } else if (flight_off_[i] != 0.0) {
            const size_t n = template_.size();
            const size_t since =
                (leg_index_[i] + n - liftoff_row_) % n;
            const size_t fl_rows = n - stance_rows_;
            const double prog = fl_rows > 0
                ? std::min(1.0, static_cast<double>(since) /
                                    static_cast<double>(fl_rows))
                : 1.0;
            if (prog >= 1.0) flight_off_[i] = 0.0;
            beta_base = row.beta + flight_off_[i] * (1.0 - prog);
        }
        last_beta_base_[i] = beta_base;
        // apex_beta_offset_ is identically 0.0 unless apex_fb_gain_ != 0,
        // so this line is bit-identical to its pre-channel form by default.
        // Applied to all four legs equally: the pronk reduces to one virtual
        // leg and the correction is a whole-body foot-placement command, not
        // a per-leg one.
        cmd->beta = beta_base * (1.0 + s * k_steer_) + s * u * gate
                    + apex_beta_offset_;
        cmd->gamma = row.gamma + gamma_openloop(static_cast<int>(i))
                     + gamma_correction(static_cast<int>(i))
                     + apex_diffcamber(static_cast<int>(i));
        // Stance-peak YIELD: inside the window after an armed touchdown, blend
        // the assembled command toward the measured angle. Identically off at
        // yield 0.0; no state touched unless enabled (the clocks are gated).
        if (gamma_acker_yield_ > 0.0) {
            const int tau = dip_since_td_ticks_[i];
            const int t0 = gamma_acker_dip_t0_ms_, t1 = gamma_acker_dip_t1_ms_;
            if (tau >= t0 && tau <= t1 && t1 > t0) {
                const double x = static_cast<double>(tau - t0) / (t1 - t0);
                const double w = gamma_acker_yield_ * 0.5 * (1.0 - std::cos(2.0 * M_PI * x));
                cmd->gamma = (1.0 - w) * cmd->gamma + w * measured_gamma(static_cast<int>(i));
            }
        }

        // fx/fz and the inertia terms stay zero, so trq_cmd_base reduces to
        // J^T * [0, fy, 0] and the rest of the law is still a pure (K, B)
        // impedance needing no contact-force estimate. See the f_lateral_
        // block above for frame, sign and gating.
        //
        // Since 2026-08-22 trq_cmd_base also carries f_clock, which
        // force_control builds from dbeta_ref below; it is a leg-frame
        // tangential force, not a body-frame one, which is why it is not
        // routed through fx/fz.
        cmd->fx = 0.0;
        cmd->fy = lateral_force(static_cast<int>(i), row.in_stance);
        cmd->fz = 0.0;
        cmd->mx = 0.0; cmd->my = 0.0; cmd->mz = 0.0;

        // The clocked-torque feedforward's rate reference (Lu & Lin eq 11's D
        // term, log S164). force_control turns this into
        //     f_clock = bz * (dbeta_ref * |hip->contact|) * e_t
        // so the tangential law damps to the clock instead of to zero.
        //
        // Gated on the SAME predicate as the gain branch below, so the
        // feedforward and the damper it corrects can never disagree about
        // which phase the leg is in.
        //
        // Flight is included only under clock_ff_phase_ == "both". The paper
        // regulates the leg in both phases (p5, S2.3) and the flight brake is
        // the LARGER of the two (b_flight 115.8 against b_tangential 30), but
        // the registered P-N-1..3 are stance predictions, so "stance" is the
        // default and "both" is its own arm.
        const bool ff_stance = leg_in_stance(static_cast<int>(i), row);
        cmd->dbeta_ref =
            (gait_striding_ ? clock_ff_scale_ : 0.0) *
            (ff_stance ? clock_rate_stance_
                       : (clock_ff_phase_ == "both" ? clock_rate_flight_ : 0.0));

        // Per-leg gain regime. With contact_gated_gains off this is exactly
        // row.in_stance for every leg, i.e. unchanged behaviour; with it on,
        // each leg gets the spring when IT is loaded rather than when the
        // template says the virtual leg is.
        if (ff_stance) {
            cmd->leg_frame = true;
            cmd->kx = k_radial_;      // along the leg: the virtual spring
            cmd->ky = k_lateral_;
            cmd->kz = k_tangential_;  // perpendicular, in the sagittal plane
            cmd->bx = b_radial_;
            cmd->by = b_lateral_;
            cmd->bz = b_tangential_;
        } else {
            cmd->leg_frame = false;
            cmd->kx = k_flight_;
            cmd->ky = k_flight_;
            cmd->kz = k_flight_;
            cmd->bx = b_flight_;
            cmd->by = b_flight_;
            cmd->bz = b_flight_;
        }
    }
    // NO per-side beta mirroring. corgi_driver already applies dir_beta
    // (+1, -1, -1, +1 for A..D from motor_config.yaml) to both the command
    // and the reported state, so the left/right mounting mirror is handled
    // there. Sending the same beta to all four legs is what makes them swing
    // the same physical direction -- which is what a pronk requires.
    //
    // exp_sim_stay does negate beta for B and C, but that is to SPLAY the
    // legs into a wide static standing stance. Applying it here double-flipped
    // the right side so it moved opposite to the left, producing a left/right
    // alternating pattern instead of a pronk: legs A and D swung +/-20 deg
    // while B and C managed only -14..+7 deg.
    //
    // steer_sign above does NOT contradict any of that, despite holding the
    // same numbers as dir_beta. dir_beta is a MOUNTING mirror the driver
    // applies on the way out; steer_sign is a left/right SELECTOR applied to a
    // deliberate perturbation, in the command convention, where equal beta
    // already means equal physical direction. The two lists coincide only
    // because A/D are the left pair and B/C the right pair in both. With
    // k_steer = steer_offset = 0 this reduces exactly to `cmd->beta =
    // row.beta`, so every result recorded before this channel existed is
    // reproducible by leaving the parameters at their defaults.
}

void GslipPronkNode::execute_standup_phase() {
    // Ramp from wherever the robot actually is, not from a hardcoded folded
    // pose. If a CSV has already stood the robot up (theta ~ 120 deg),
    // starting the ramp at 17 deg commands an immediate collapse.
    //
    // A single spin_some() is NOT enough: the subscription has not yet
    // discovered the publisher at construction time, so motor_state_ is still
    // zero-initialised and the fallback fires even though the robot is
    // standing. Wait for a real sample. Wall-clock sleep, deliberately -- this
    // must work before the sim clock is known to be running.
    const int kMaxWaitMs = 5000;
    int waited_ms = 0;
    while (rclcpp::ok() && motor_state_.module_a.theta == 0.0 && waited_ms < kMaxWaitMs) {
        rclcpp::spin_some(this->get_node_base_interface());
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        waited_ms += 10;
    }

    double theta_start = motor_state_.module_a.theta;
    double beta_start = motor_state_.module_a.beta;
    if (theta_start == 0.0) {
        theta_start = 17.0 / 180.0 * M_PI;
        beta_start = 0.0;
        RCLCPP_ERROR(this->get_logger(),
                     "No motor/state after %d ms. Assuming the folded pose, which will "
                     "COLLAPSE a standing robot. Check that the simulator is running.",
                     kMaxWaitMs);
    } else {
        RCLCPP_INFO(this->get_logger(), "Got motor/state after %d ms", waited_ms);
    }

    const TemplateRow& first = template_.front();

    // Wait for force_control to be ALIVE AND PUBLISHING before ramping.
    //
    // Measured 2026-09-01, bag standup_033150:
    //     imp theta  msgs  1.78 - 17.75   producer up from 1.78
    //     cmd theta  msgs  3.90 - 17.77   consumer silent until 3.90
    // The ramp (1.78-3.74) finished before force_control emitted anything.
    // It was not dropping the ramp -- it was not running yet.
    //
    // The first version of this guard waited on
    // get_subscription_count("impedance/command"), which counts ANY
    // subscriber including `ros2 bag record`. With a bag running it
    // returned instantly, so the guard was inert precisely when it was
    // being measured. count_publishers("motor/command") instead tests the
    // thing that matters: the consumer is up and producing.
    //
    // Still a timeout, so a solo run (no force_control) works, and the
    // outcome is logged either way -- a ramp published to nobody should
    // never again be invisible in the banner.
    {
        const int kWaitMs = 5000;
        int waited = 0;
        while (rclcpp::ok() && this->count_publishers("motor/command") == 0
               && waited < kWaitMs) {
            rclcpp::spin_some(this->get_node_base_interface());
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
            waited += 10;
        }
        const size_t cons = this->count_publishers("motor/command");
        const size_t subs = imp_cmd_pub_->get_subscription_count();
        if (cons == 0) {
            RCLCPP_WARN(this->get_logger(),
                        "force_control is NOT PUBLISHING motor/command after "
                        "%d ms (%zu subscriber(s) on impedance/command, which "
                        "may just be a bag). Ramping anyway -- expect the leg "
                        "to sit still and then lurch when it starts.",
                        kWaitMs, subs);
        } else {
            RCLCPP_INFO(this->get_logger(),
                        "consumer ready after %d ms: %zu motor/command "
                        "publisher(s), %zu impedance/command subscriber(s)",
                        waited, cons, subs);
        }
    }

    RCLCPP_INFO(this->get_logger(),
                "Ramping from measured theta=%.1f deg to template theta=%.1f deg",
                theta_start * 180.0 / M_PI, first.theta * 180.0 / M_PI);

    rclcpp::Duration period(0, 1000000);  // 1 ms
    rclcpp::Time next_time = this->now();

    for (int i = 0; i < standup_ticks_ && rclcpp::ok(); i++) {
        rclcpp::spin_some(this->get_node_base_interface());

        const double s = static_cast<double>(i) / standup_ticks_;
        TemplateRow row{};
        row.t = 0.0;
        row.theta = theta_start + s * (first.theta - theta_start);
        row.beta = beta_start + s * (first.beta - beta_start);
        row.gamma = 0.0;
        row.in_stance = false;  // soft gains while posing
        apply_row(row);

        imp_cmd_.header.stamp = this->now();
        imp_cmd_pub_->publish(imp_cmd_);

        next_time = next_time + period;
        rclcpp::sleep_for(std::chrono::nanoseconds(
            std::max<int64_t>(0, (next_time - this->now()).nanoseconds())));
    }
}

void GslipPronkNode::execute_running_phase() {
    rclcpp::Duration period(0, 1000000);  // 1 ms
    rclcpp::Time next_time = this->now();

    // Latch the heading to hold. Taken AFTER the settle, so the block-removal
    // transient is not baked into the reference.
    yaw_ref_set_ = false;

    // Let the robot settle onto its legs before striding. In experiment mode
    // the trigger that got us here also removed the support box.
    //
    // The settle doubles as the event scheduler's contact-rate measurement
    // window: message count and sim time are sampled across it, so the
    // precondition check costs no extra wall time.
    const long rate_count0 = contact_msg_count_;
    const double rate_t0 = this->now().seconds();
    if (settle_ticks_ > 0) {
        RCLCPP_INFO(this->get_logger(), "Settling for %d ms before the first stride",
                    settle_ticks_);
        TemplateRow settle = template_.front();
        settle.in_stance = true;
        for (int i = 0; i < settle_ticks_ && rclcpp::ok() && trigger_; i++) {
            rclcpp::spin_some(this->get_node_base_interface());
            apply_row(settle);
            imp_cmd_.header.stamp = this->now();
            imp_cmd_pub_->publish(imp_cmd_);
            next_time = next_time + period;
            rclcpp::sleep_for(std::chrono::nanoseconds(
                std::max<int64_t>(0, (next_time - this->now()).nanoseconds())));
        }
    }

    // Event-scheduler engagement decision, once per running phase. Refusal
    // is grep-able and falls back to the global clock -- the harness
    // asserts ENGAGED on scheduler runs the same way it asserts ACKER.
    event_engaged_ = false;
    if (event_sched_) {
        const double rate_dt = this->now().seconds() - rate_t0;
        const double rate =
            rate_dt > 0.1
                ? static_cast<double>(contact_msg_count_ - rate_count0) /
                      rate_dt
                : 0.0;
        if (!sched_labels_ok_) {
            RCLCPP_ERROR(this->get_logger(),
                         "EVENT SCHED REFUSED: template labels unusable "
                         "(see load_template). Global clock.");
        } else if (settle_ticks_ <= 0) {
            RCLCPP_ERROR(this->get_logger(),
                         "EVENT SCHED REFUSED: settle_ticks=0 leaves no "
                         "window to verify the contact rate. Global clock.");
        } else if (rate < 500.0) {
            RCLCPP_ERROR(this->get_logger(),
                         "EVENT SCHED REFUSED: contact rate %.0f Hz < 500 "
                         "(trigger latency would be several strides' worth "
                         "of rows). Set CORGI_CONTACT_INTERVAL=1. Global "
                         "clock.", rate);
        } else {
            event_engaged_ = true;
            sched_reset(0);
            if (std::getenv("CORGI_SCHED_DEBUG") &&
                std::string(std::getenv("CORGI_SCHED_DEBUG")) == "1") {
                sched_csv_.open("/tmp/corgi_sched_events.csv",
                                std::ios::trunc);
                if (sched_csv_.is_open())
                    sched_csv_ << "t_node,leg,leg_index,master_index,"
                                  "phase_err_rows,snap_rows_pending,"
                                  "in_stance_row,contact_stable,event\n";
            }
            RCLCPP_WARN(this->get_logger(),
                        "EVENT SCHED ENGAGED: snap_limit=%.3fs blend=%d "
                        "arm=%d snap/stride=%d fwd_only=%s "
                        "contact_rate=%.0fHz (onset row %zu, hard-snap "
                        "bound %.2f deg, sched csv %s)",
                        event_snap_limit_s_, event_blend_ticks_,
                        event_arm_strides_, event_snap_per_stride_,
                        event_forward_only_ ? "YES" : "no", rate,
                        stance_onset_row_,
                        sched_hard_snap_beta_deg_,
                        sched_csv_.is_open() ? "ON" : "off");
        }
    }

    if (event_engaged_ && couple_gain_ != 0.0) {
        RCLCPP_WARN(this->get_logger(),
                    "PHASE COUPLING ENGAGED: gain=%.4f clamp=%.3f "
                    "rows/tick (flight rows only)",
                    couple_gain_, couple_clamp_);
    }

    // Tier 3 slaved-stance engagement, once per running phase.
    slave_engaged_ = false;
    slave_active_ = false;
    if (slave_stance_) {
        if (!event_engaged_) {
            RCLCPP_ERROR(this->get_logger(),
                         "SLAVE STANCE REFUSED: event scheduler did not "
                         "engage. Clocked replay.");
        } else if (!lut_ok_) {
            RCLCPP_ERROR(this->get_logger(),
                         "SLAVE STANCE REFUSED: no usable L(theta) LUT. "
                         "Clocked replay.");
        } else if (slave_v_source_ == "ekf" && ekf_stamp_ < 0.0) {
            RCLCPP_ERROR(this->get_logger(),
                         "SLAVE STANCE REFUSED: slave_v_source=ekf and no "
                         "/ekf message has arrived. Clocked replay.");
        } else {
            slave_engaged_ = true;
            slave_active_ = true;
            if (push_sync_) {
                RCLCPP_WARN(this->get_logger(),
                            "PUSH SYNC ENGAGED: quorum=%d max_hold=%.3fs "
                            "arm=%d strides (early legs hold beta at "
                            "entry under stance gains until the quorum "
                            "lands, then all release together; a sole "
                            "support leg never holds)",
                            push_sync_quorum_, push_sync_max_hold_s_,
                            push_sync_arm_strides_);
            }
            RCLCPP_WARN(this->get_logger(),
                        "SLAVE STANCE ENGAGED: v_source=%s v_fixed=%.3f "
                        "m/s sweep=%.4f rad over <=%.0f ticks, LUT %zu "
                        "rows, L(onset theta)=%.4f m",
                        slave_v_source_.c_str(), slave_v_fixed_,
                        stance_sweep_rad_,
                        stance_max_overrun_ratio_ *
                            static_cast<double>(stance_rows_),
                        lut_theta_.size(),
                        lut_L(template_[stance_onset_row_].theta));
        }
    }

    update_attitude(roll_, pitch_, yaw_);
    yaw_ref_ = yaw_;
    yaw_ref_set_ = true;
    if (gamma_acker_dir_ != 0.0) {
        // Grep-able engagement announcement, same pattern as STANCE LABEL
        // DUTY: the harness asserts this line per run, because a camber
        // command that silently failed to engage looks exactly like "camber
        // does not curve the path" -- the one wrong answer this experiment
        // cannot afford.
        RCLCPP_WARN(this->get_logger(),
                    "ACKER CAMBER set: in=%.2f deg out=%.2f deg dir=%+.0f "
                    "(ramp %d ms, clamp %.1f deg)",
                    gamma_acker_in_ * 180.0 / M_PI,
                    gamma_acker_out_ * 180.0 / M_PI,
                    gamma_acker_dir_,
                    gamma_acker_ramp_ticks_,
                    gamma_acker_limit_ * 180.0 / M_PI);
        if (gamma_acker_dip_ > 0.0) {
            // Separate line so the ACKER banner above stays byte-identical
            // for every existing harness's grep; absent when the dip is off.
            RCLCPP_WARN(this->get_logger(),
                        "ACKER DIP set: %.2f of the camber term over %d-%d ms "
                        "after debounced touchdown (rearm %d ms)",
                        gamma_acker_dip_, gamma_acker_dip_t0_ms_,
                        gamma_acker_dip_t1_ms_, gamma_acker_dip_rearm_ms_);
        }
        if (gamma_acker_yield_ > 0.0) {
            RCLCPP_WARN(this->get_logger(),
                        "ACKER YIELD set: %.2f toward the MEASURED gamma over %d-%d ms "
                        "after debounced touchdown (rearm %d ms)",
                        gamma_acker_yield_, gamma_acker_dip_t0_ms_,
                        gamma_acker_dip_t1_ms_, gamma_acker_dip_rearm_ms_);
        }
    }
    if (gamma_acker_ff_ > 0.0) {
        // Closed-loop camber engagement announcement, harness-certified per
        // run like the ACKER CAMBER line above (which stays byte-identical
        // and dir-gated -- open-loop harness greps must not match a CL run).
        RCLCPP_WARN(this->get_logger(),
                    "ACKER CL set: ff=%.2f deg k_yaw=%.3f d_yaw=%.3f "
                    "range=[%.2f, %.2f] deg (ramp %d ms, clamp %.1f deg)",
                    gamma_acker_ff_ * 180.0 / M_PI,
                    k_acker_yaw_, d_acker_yaw_,
                    gamma_acker_min_ * 180.0 / M_PI,
                    gamma_acker_hi_ * 180.0 / M_PI,
                    gamma_acker_ramp_ticks_,
                    gamma_acker_limit_ * 180.0 / M_PI);
        if (gamma_acker_dip_ > 0.0) {
            RCLCPP_WARN(this->get_logger(),
                        "ACKER DIP set: %.2f of the camber term over %d-%d ms "
                        "after debounced touchdown (rearm %d ms)",
                        gamma_acker_dip_, gamma_acker_dip_t0_ms_,
                        gamma_acker_dip_t1_ms_, gamma_acker_dip_rearm_ms_);
        }
        if (gamma_acker_yield_ > 0.0) {
            RCLCPP_WARN(this->get_logger(),
                        "ACKER YIELD set: %.2f toward the MEASURED gamma over %d-%d ms "
                        "after debounced touchdown (rearm %d ms)",
                        gamma_acker_yield_, gamma_acker_dip_t0_ms_,
                        gamma_acker_dip_t1_ms_, gamma_acker_dip_rearm_ms_);
        }
    }
    if (gamma_yaw_limit_ > 0.0) {
        // Same grep-able engagement pattern as ACKER CAMBER: a clamp that
        // silently failed to engage looks exactly like "the floor did not
        // move". Runs are NOT comparable to unclamped campaigns.
        RCLCPP_WARN(this->get_logger(),
                    "GENTLE YAW CLAMP set: +-%.2f deg on the yaw term alone "
                    "(k_yaw=%.2f d_yaw=%.2f)",
                    gamma_yaw_limit_ * 180.0 / M_PI, k_yaw_, d_yaw_);
    }
    // Announce the attitude gains UNCONDITIONALLY.
    //
    // WHY. Until 2026-08-22 k_yaw appeared in exactly one log line -- inside
    // the `gamma_yaw_limit_ > 0` branch above -- so a run with the clamp OFF
    // printed nothing about the heading loop at all. That is fine until you
    // run the experiment that turns k_yaw OFF (P-M-1, S163): the arm whose
    // engagement matters most is then the one arm with nothing to grep, and
    // `k_yaw:=0.0` silently failing to reach the node is indistinguishable
    // from "turning the heading controller off changes nothing" -- a
    // confident wrong answer on a registered gate. S138 and S146 each cost a
    // campaign to exactly this.
    //
    // PROOF OF INTENT ONLY: it proves the parameters were READ, not that they
    // reached gamma_correction(). The proof of ACTION is the front/rear camber
    // split itself (S162) -- with k_yaw = 0 it must VANISH, measurable per arm
    // with scripts/diag/audit_gamma_decomp.py.
    RCLCPP_WARN(this->get_logger(),
                "ATTITUDE GAINS: k_yaw=%.4f d_yaw=%.4f | k_roll=%.4f "
                "d_roll=%.4f | gamma_limit=%.2f deg gamma_yaw_limit=%.2f deg "
                "(%s)",
                k_yaw_, d_yaw_, k_roll_, d_roll_,
                gamma_limit_ * 180.0 / M_PI,
                gamma_yaw_limit_ * 180.0 / M_PI,
                gamma_yaw_limit_ > 0.0 ? "yaw term CLAMPED"
                                       : "yaw clamp OFF -- the yaw term can "
                                         "saturate into a commanded lean");
    RCLCPP_INFO(this->get_logger(),
                // f_lateral and settle_ticks are echoed because a parameter
                // that never reaches the node looks EXACTLY like a parameter
                // that does nothing. Both were unreachable from the launch
                // file until 2026-08-17, and an entire f_lateral sweep ran at
                // 0.0 without a single sign that anything was wrong. Anything
                // an experiment varies belongs on this line.
                "Running the G-SLIP pronk template. Holding heading %.1f deg "
                "(k_roll=%.2f k_yaw=%.2f, gamma limit %.1f deg, "
                "f_lateral=%.2f N%s, settle_ticks=%d)",
                yaw_ref_ * 180.0 / M_PI, k_roll_, k_yaw_,
                gamma_limit_ * 180.0 / M_PI,
                f_lateral_,
                f_lateral_front_only_ ? " (front only)" : "",
                settle_ticks_);
    // Printed every run, so /tmp/ramp_ctl.log always records what the steering
    // channel was actually asked for. A sweep is only as good as the record of
    // which value produced which dump.
    RCLCPP_INFO(this->get_logger(),
                "Steering: k_steer=%.3f steer_offset=%.2f deg "
                "(stance-gated, prepose %s) k_steer_yaw=%.3f d_steer_yaw=%.3f "
                "limit %.1f deg",
                k_steer_, steer_offset_ * 180.0 / M_PI,
                steer_prepose_ ? "ON" : "off", k_steer_yaw_, d_steer_yaw_,
                steer_limit_ * 180.0 / M_PI);
    // Separate line, so a grep for "Turn:" over /tmp/ramp_ctl.log identifies the
    // commanded radius of a dump without re-reading the invocation.
    RCLCPP_INFO(this->get_logger(),
                "Turn: turn_rate=%.4f rad/s (%.2f deg/s), err limit %.1f deg%s",
                turn_rate_, turn_rate_ * 180.0 / M_PI,
                turn_err_limit_ * 180.0 / M_PI,
                turn_rate_ == 0.0 ? "  -- HEADING HOLD, no turn commanded" : "");
    // Grep-able, and WARN so it survives the harness's log level -- same
    // pattern as ACKER CAMBER / GENTLE YAW CLAMP. The swing gains were the
    // last experiment-varied parameters NOT on an announcement line, which
    // is exactly the hole the f_lateral sweep fell through (a whole matrix
    // ran at 0.0 with nothing in the logs to say so). The k_flight campaign
    // (log S103) varies these, so they belong here.
    RCLCPP_WARN(this->get_logger(),
                "FLIGHT GAINS set: k_flight=%.1f b_flight=%.1f "
                "(default 12000.0/150.0)",
                k_flight_, b_flight_);
    if (k_pitch_ != 0.0 || d_pitch_ != 0.0) {
        // Grep-able engagement announcement, same contract as ACKER
        // CAMBER / GENTLE YAW CLAMP / FLIGHT GAINS: a run that asked for
        // the pitch channel and did not log this line is INVALID.
        RCLCPP_WARN(this->get_logger(),
                    "PITCH CHANNEL set: k_pitch=%.3f d_pitch=%.3f "
                    "clamp %.2f deg (differential theta, front A/B vs "
                    "rear C/D, stance-gated)",
                    k_pitch_, d_pitch_, pitch_limit_ * 180.0 / M_PI);
    }
    if (apex_fb_gain_ != 0.0) {
        // Same contract as ACKER CAMBER / GENTLE YAW CLAMP / FLIGHT GAINS /
        // PITCH CHANNEL: a run that asked for this channel and did not log
        // this line is INVALID. NOTE that this line alone is NOT sufficient --
        // it announces intent, not action. The APEX BETA FB FIRED line at
        // shutdown is what proves the channel did anything.
        RCLCPP_WARN(this->get_logger(),
                    "APEX BETA FB set: gain=%.3f k_vx=%.4f k_h=%.4f "
                    "vx*=%.4f m/s h*=%.4f m clamp %.2f deg "
                    "(one correction per flight, held)",
                    apex_fb_gain_, apex_k_vx_, apex_k_h_, apex_vx_star_,
                    apex_h_star_, apex_beta_limit_ * 180.0 / M_PI);
    }
    if (apex_dc_gain_ != 0.0) {
        // Same contract as APEX BETA FB above: this line announces intent;
        // the APEX DIFF CAMBER FIRED line proves action. A run that asked
        // for this channel and did not log this line is INVALID.
        RCLCPP_WARN(this->get_logger(),
                    "APEX DIFF CAMBER set: gain=%.3f k_vy=%.4f k_rho=%.4f "
                    "k_drho=%.4f clamp %.2f deg (lam_l on A/D, mirrored on "
                    "B/C; one correction per flight, held)",
                    apex_dc_gain_, apex_dc_k_vy_, apex_dc_k_rho_,
                    apex_dc_k_drho_, apex_dc_limit_ * 180.0 / M_PI);
    }
    if (apex_fb_gain_ != 0.0 || apex_dc_gain_ != 0.0) {
        // The latch-up guard's announcement, same contract as the channel
        // banners above. Grep for the 'APEX HOLD DECAY:' action line to
        // know whether it ever actually fired in a run.
        RCLCPP_WARN(this->get_logger(),
                    "APEX HOLD DECAY set: grace=%.2f s decay=%.2f s%s",
                    apex_hold_grace_s_, apex_hold_decay_s_,
                    apex_hold_decay_s_ == 0.0
                        ? "  <-- DISABLED: held offsets can latch at full "
                          "scale if the gait loses flight (the S268 mode)"
                        : "");
    }
    size_t index = 0;
    size_t stride_count = 0;

    // The clock is running from here and only here. See gait_striding_.
    gait_striding_ = true;
    struct StrideGuard {
        bool* f;
        ~StrideGuard() { *f = false; }
    } stride_guard{&gait_striding_};

    while (rclcpp::ok() && trigger_) {
        rclcpp::spin_some(this->get_node_base_interface());
        // Before apply_row, so a correction found this tick is used this tick.
        update_apex_feedback();

        // Before apply_row, so the row is commanded against this tick's
        // reference. period is 1 ms; hard-coding the same figure here would be
        // a second place to change the tick rate.
        advance_yaw_ref(period.nanoseconds() * 1e-9);

        if (event_engaged_) {
            // Edge detection + snap on this tick's contact, rows selected
            // from the per-leg clocks, clocks advanced for the next tick.
            sched_tick(index, stride_count, this->now().seconds());
            apply_rows({&template_[leg_index_[0]],
                        &template_[leg_index_[1]],
                        &template_[leg_index_[2]],
                        &template_[leg_index_[3]]});
        } else {
            // event_sched off (or refused): EXACTLY the historical path.
            apply_row(template_[index]);
        }
        imp_cmd_.header.stamp = this->now();
        imp_cmd_pub_->publish(imp_cmd_);

        if (event_engaged_) sched_advance();
        index++;
        if (index >= template_.size()) {
            index = 0;
            stride_count++;
            if (stride_count % 10 == 0) {
                RCLCPP_INFO(this->get_logger(), "%zu strides", stride_count);
                // Push-sync telemetry rides the stride line, NOT the end
                // of the running phase: a campaign run is killed by
                // teardown and never exits the loop, so an end-of-run
                // summary is never printed (empty assert, 2026-08-20).
                const long tot = push_rel_quorum_ + push_rel_timeout_ +
                                 push_rel_sole_;
                if (push_sync_ && tot > 0) {
                    RCLCPP_WARN(this->get_logger(),
                                "PUSH SYNC RELEASES: quorum %ld (%.0f%%) "
                                "timeout %ld sole %ld",
                                push_rel_quorum_,
                                100.0 * static_cast<double>(
                                            push_rel_quorum_) /
                                    static_cast<double>(tot),
                                push_rel_timeout_, push_rel_sole_);
                }
            }
        }

        next_time = next_time + period;
        rclcpp::sleep_for(std::chrono::nanoseconds(
            std::max<int64_t>(0, (next_time - this->now()).nanoseconds())));
    }

    if (sched_csv_.is_open()) sched_csv_.close();
    RCLCPP_INFO(this->get_logger(), "Stopped after %zu strides", stride_count);
}

void GslipPronkNode::run() {
    execute_standup_phase();

    rclcpp::Duration period(0, 1000000);  // 1 ms
    rclcpp::Time next_time = this->now();

    RCLCPP_INFO(this->get_logger(), "Holding pose; waiting for trigger");
    while (rclcpp::ok()) {
        rclcpp::spin_some(this->get_node_base_interface());

        if (trigger_) {
            execute_running_phase();
        } else {
            TemplateRow hold = template_.front();
            hold.in_stance = hold_stance_;
            apply_row(hold);
            imp_cmd_.header.stamp = this->now();
            imp_cmd_pub_->publish(imp_cmd_);
        }

        next_time = next_time + period;
        rclcpp::sleep_for(std::chrono::nanoseconds(
            std::max<int64_t>(0, (next_time - this->now()).nanoseconds())));
    }

    // S296: engagement is scored on COUNTS, never on the 1-in-20
    // throttled FIRED lines (that conflation mis-read S292 by ~15x).
    // Printed only when an apex channel was on, so off runs stay
    // log-identical.
    if (apex_fb_gain_ != 0.0 || apex_dc_gain_ != 0.0) {
        RCLCPP_WARN(this->get_logger(),
                    "APEX ENGAGEMENT: final apex_count_=%ld", apex_count_);
    }
}


// ---------------------------------------------------------------------
// S313: real-time scheduling for the 1 kHz control loops.
//
// On 2026-08-31 two of three hardware air runs published motor commands
// whose VALUES changed at ~15 Hz while every timestamp still said 1 kHz:
// force_control was publishing on schedule but consuming stale imp_cmd,
// i.e. its single-threaded spin_some loop was being starved of CPU
// (desktop/remote-desktop encoding is the leading suspect). The robot is
// then step-commanded in ~50x jumps -- the observed "spazzing".
//
// SCHED_FIFO makes these loops immune to that class of load. It needs
// privilege (CAP_SYS_NICE or root); WITHOUT it we warn and continue at
// normal priority rather than refusing to start -- a controller that
// will not launch is worse than one that is merely not real-time.
//
// Off with CORGI_RT_PRIORITY=0. Grant the privilege with:
//   sudo setcap cap_sys_nice+ep <binary>      (per binary, survives runs)
//   or launch under: chrt -f 80 <command>
static void corgi_try_realtime(const rclcpp::Logger& log) {
    const char* env = std::getenv("CORGI_RT_PRIORITY");
    int prio = env ? std::atoi(env) : 80;
    if (prio <= 0) {
        RCLCPP_WARN(log, "REALTIME: disabled (CORGI_RT_PRIORITY=%d)", prio);
        return;
    }
    struct sched_param sp;
    sp.sched_priority = prio;
    if (sched_setscheduler(0, SCHED_FIFO, &sp) == 0) {
        RCLCPP_WARN(log, "REALTIME: SCHED_FIFO priority %d ACQUIRED -- the "
                         "1 kHz loop is protected from desktop/encoder load",
                    prio);
    } else {
        RCLCPP_WARN(log, "REALTIME: could NOT set SCHED_FIFO %d (%s). Running "
                         "at normal priority: the 1 kHz loop is vulnerable to "
                         "CPU load and commands may degrade to ~15 Hz (S313). "
                         "Fix: sudo setcap cap_sys_nice+ep on the binary, or "
                         "launch under 'chrt -f %d'.",
                    prio, std::strerror(errno), prio);
    }
}

int main(int argc, char** argv) {
    rclcpp::init(argc, argv);
    auto node = std::make_shared<GslipPronkNode>();
    corgi_try_realtime(node->get_logger());
    node->run();
    rclcpp::shutdown();
    return 0;
}
